window.BIOMASTER.MCQ_MOLECULAR = [{"id":"MCQ-MO-001","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân tử","q":"Một phân tử DNA mạch kép có tổng số $3000$ nucleotide và có Adenine chiếm $20\\%$. Số liên kết Hydrogen của phân tử DNA này là:","opts":["$4200$.","$3900$.","$3600$.","$3000$."],"ans":1,"exp":"$A = T = 600; G = C = 900 \\Rightarrow H = 2A + 3G = 3900$."},{"id":"MCQ-MO-002","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phân tử","q":"Một gen ở vi khuẩn có $1800$ cặp nucleotide tiến hành phiên mã và dịch mã. Số amino acid trong phân tử protein hoàn chỉnh (sau khi cắt bỏ aa mở đầu) là:","opts":["$598$.","$298$.","$600$.","$599$."],"ans":0,"exp":"Số bộ ba $= \\frac{1800}{3} = 600$. Số aa trong protein hoàn chỉnh $= 600 - 2 = 598$."},{"id":"MCQ-MO-003","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân đôi DNA","q":"Trong quá trình nhân đôi DNA ở <i>E. coli</i>, enzyme nào có vai trò tháo xoắn và cắt đứt các liên kết Hydrogen giữa hai mạch đơn?","opts":["DNA polymerase III.","DNA ligase.","Helicase.","Primase (RNA polymerase)."],"ans":2,"exp":"Enzyme Helicase sử dụng ATP để tháo xoắn và tách hai mạch đơn tại chạc chữ Y."},{"id":"MCQ-MO-004","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Mã di truyền","q":"Bộ ba mở đầu trên mRNA là $5^\\prime\\text{AUG}3^\\prime$. Vậy bộ ba đối mã (anticodon) tương ứng trên tRNA vận chuyển Methionine và bộ ba trên mạch khuôn của gen lần lượt là:","opts":["$3^\\prime\\text{UAC}5^\\prime$ và $3^\\prime\\text{TAC}5^\\prime$.","$3^\\prime\\text{UAG}5^\\prime$ và $3^\\prime\\text{ATC}5^\\prime$.","$3^\\prime\\text{AUG}5^\\prime$ và $3^\\prime\\text{ATG}5^\\prime$.","$5^\\prime\\text{UAC}3^\\prime$ và $5^\\prime\\text{TAC}3^\\prime$."],"ans":0,"exp":"Bắt cặp ngược chiều: Codon $5^\\prime\\text{AUG}3^\\prime$ khớp với Anticodon $3^\\prime\\text{UAC}5^\\prime$ và được phiên mã từ bộ ba mạch gốc $3^\\prime\\text{TAC}5^\\prime$."},{"id":"MCQ-MO-005","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Operon Lac","q":"Trong mô hình Operon Lac ở vi khuẩn <i>E. coli</i>, khi môi trường có đường lactose, phân tử allolactose sẽ gắn vào cấu trúc nào để mở khóa quá trình phiên mã?","opts":["Protein ức chế (làm biến đổi cấu hình khiến nó không gắn được vào $O$).","Gen điều hòa ($lacI$).","Vùng vận hành (Operator - $O$).","Vùng khởi động (Promoter - $P$)."],"ans":0,"exp":"Allolactose là chất cảm ứng gắn trực tiếp vào protein ức chế làm bất hoạt protein này."},{"id":"MCQ-MO-006","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến điểm","q":"Đột biến thay thế một cặp nucleotide $G-C$ bằng một cặp $A-T$ sẽ làm số liên kết Hydrogen của gen thay đổi như thế nào?","opts":["Giảm 1 liên kết Hydrogen.","Giảm 3 liên kết Hydrogen.","Không thay đổi.","Tăng 1 liên kết Hydrogen."],"ans":0,"exp":"Cặp $G-C$ có 3 liên kết H, cặp $A-T$ có 2 liên kết H $\\Rightarrow$ thay $G-C$ bằng $A-T$ làm giảm 1 liên kết H."},{"id":"MCQ-MO-007","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Công nghệ Gen","q":"Trong kỹ thuật chuyển gen vào vi khuẩn <i>E. coli</i>, thể truyền (vector) phổ biến nhất là phân tử DNA nhỏ, dạng vòng, có khả năng tự nhân đôi độc lập với DNA vùng nhân của vi khuẩn, được gọi là:","opts":["Nhiễm sắc thể nhân tạo nấm men.","Nucleosome.","Plasmid.","Ribosome."],"ans":2,"exp":"Plasmid là phân tử DNA mạch kép dạng vòng nhỏ nằm trong tế bào chất của vi khuẩn, được dùng làm vector chuyển gen."},{"id":"MCQ-MO-008","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến 5-BU","q":"Một gen có cặp $A-T$ bị tác động bởi 1 phân tử 5-BU ngay ở lần nhân đôi thứ nhất, sau đó chuyển sang môi trường bình thường không còn 5-BU và nhân đôi thêm 3 lần nữa (tổng 4 lần). Số gen đột biến $G-C$ hoàn chỉnh tạo ra là:","opts":["$7$ gen.","$1$ gen.","$4$ gen.","$3$ gen."],"ans":3,"exp":"Với $k = 4$ lần nhân đôi: Số gen đột biến $G-C = 2^{4-2} - 1 = 3$ gen."},{"id":"MCQ-MO-009","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đồng vị phóng xạ","q":"Có 3 phân tử DNA của <i>E. coli</i> chỉ chứa $^{15}\\text{N}$ được nuôi trong môi trường $^{14}\\text{N}$ nhân đôi 4 lần, sau đó chuyển sang môi trường $^{15}\\text{N}$ nhân đôi thêm 1 lần nữa. Số phân tử DNA chứa cả $^{15}\\text{N}$ và $^{14}\\text{N}$ ở cuối quá trình là:","opts":["$48$.","$90$.","$42$.","$96$."],"ans":1,"exp":"Sau 4 lần nhân đôi ở $^{14}\\text{N}$ có $3 \\times 2^4 \\times 2 - 6 = 90$ mạch đơn $^{14}\\text{N}$. Khi nhân đôi 1 lần ở $^{15}\\text{N}$, 90 mạch này tạo đúng 90 phân tử DNA lai."},{"id":"MCQ-MO-010","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phiên mã","q":"Một gen có chiều dài $5100\\text{ \\AA}$ và hiệu số giữa Adenine với loại không bổ sung bằng $10\\%$ tổng số nu. Trên mạch gốc của gen có $A_1 = 150$ và $G_1 = 300$. Khi gen phiên mã 1 lần, số ribonucleotide loại $rU$ và $rC$ môi trường cung cấp lần lượt là:","opts":["$rU = 750$ và $rC = 300$.","$rU = 150$ và $rC = 600$.","$rU = 300$ và $rC = 150$.","$rU = 150$ và $rC = 300$."],"ans":3,"exp":"Theo nguyên tắc bổ sung trong phiên mã: $rU_{\\text{mRNA}} = A_{\\text{gốc}} = A_1 = 150$; $rC_{\\text{mRNA}} = G_{\\text{gốc}} = G_1 = 300$."},{"id":"MCQ-MO-011","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cắt nối Exon","q":"Một gen ở sinh vật nhân thực có 6 đoạn Exon (E1, E2, E3, E4, E5, E6) và 5 đoạn Intron. Quá trình cắt nối thay thế luôn giữ lại E1 ở đầu và E6 ở cuối, các Exon ở giữa có thể được giữ lại hoặc cắt bỏ (không đảo thứ tự). Số loại phân tử mRNA trưởng thành khác nhau tối đa tạo ra là:","opts":["$24$ loại.","$32$ loại.","$16$ loại.","$8$ loại."],"ans":2,"exp":"Có $4$ đoạn Exon ở giữa (E2, E3, E4, E5), mỗi đoạn có 2 khả năng (giữ lại hoặc cắt bỏ) $\\Rightarrow$ Số loại mRNA trưởng thành $= 2^4 = 16$ loại."},{"id":"MCQ-MO-012","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến dịch khung","q":"Một phân tử mRNA nhân tạo có trình tự lặp lại liên tục $5^\\prime\\text{AUAUAUAUAUAU...}3^\\prime$. Trong hệ thống dịch mã nhân tạo không cần bộ ba mở đầu, chuỗi polypeptide tạo thành sẽ có đặc điểm gì? Nếu chèn thêm 1 nu loại $G$ vào giữa mạch mRNA này thì sao?","opts":["Không dịch mã được.","Tạo chuỗi chỉ gồm 1 loại amino acid; chèn 1 nu $G$ làm dừng dịch mã ngay.","Tạo chuỗi gồm 2 loại amino acid xen kẽ ($\\text{Ile}-\\text{Tyr}-\\text{Ile}-\\text{Tyr}...$); chèn 1 nu $G$ làm thay đổi đúng 1 amino acid tại điểm chèn rồi tiếp tục lặp lại 2 loại aa đó.","Tạo chuỗi gồm 3 loại amino acid; chèn 1 nu $G$ làm thay đổi toàn bộ phía sau."],"ans":2,"exp":"Trình tự đọc theo từng bộ 3: $\\text{AUA}-\\text{UAU}-\\text{AUA}-\\text{UAU}$ (2 loại aa xen kẽ). Nếu chèn 1 nu $G$, sau vị trí chèn khung đọc vẫn quay lại nhịp xen kẽ $\\text{UAU}-\\text{AUA}$!"},{"id":"MCQ-MO-013","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chạc chữ Y","q":"Một phân tử DNA mạch kép ở sinh vật nhân thực có 10 đơn vị tái bản đang hoạt động đồng thời. Trên mỗi chạc chữ Y, mạch tổng hợp gián đoạn tạo ra trung bình 15 đoạn Okazaki. Tổng số đoạn mồi RNA đã được enzyme Primase tổng hợp trên toàn bộ phân tử DNA này là:","opts":["$160$ đoạn mồi.","$320$ đoạn mồi.","$310$ đoạn mồi.","$170$ đoạn mồi."],"ans":1,"exp":"10 đơn vị tái bản có $10 \\times 2 = 20$ chạc chữ Y. Trên mỗi chạc chữ Y có 1 mạch liên tục (cần 1 mồi) và 1 mạch gián đoạn (cần 15 mồi) $= 16$ mồi/chạc $\\Rightarrow$ Tổng số đoạn mồi $= 20 \\times 16 = 320$ đoạn mồi."},{"id":"MCQ-MO-014","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sinh tổng hợp cDNA","q":"Để sản xuất hormone Insulin người trong tế bào vi khuẩn <i>E. coli</i>, các nhà khoa học không lấy trực tiếp gen Insulin từ hệ gen trong nhân tế bào người mà phải tách chiết mRNA trưởng thành rồi dùng enzyme phiên mã ngược (Reverse Transcriptase) tạo cDNA. Lý do chính là gì?","opts":["Vì gen của người phân mảnh (có các đoạn Intron), còn vi khuẩn <i>E. coli</i> không có bộ máy cắt bỏ Intron (Spliceosome) nên không thể xử lý tiền mRNA.","Vì gen trong nhân tế bào người quá ngắn.","Vì vi khuẩn chỉ phiên mã được từ cDNA.","Vì mã di truyền của người và vi khuẩn hoàn toàn khác nhau."],"ans":0,"exp":"Gen nhân thực chứa các đoạn Intron không mã hóa. Vi khuẩn nhân sơ thiếu bộ máy Spliceosome để cắt Intron, nên phải dùng cDNA (tạo từ mRNA trưởng thành đã cắt hết Intron)."},{"id":"MCQ-MO-015","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Kỹ thuật PCR - Đề HSG Tỉnh","q":"Từ 1 phân tử DNA mạch kép ban đầu, nhân bản đoạn gen mục tiêu bằng PCR qua 6 chu kỳ. Số phân tử DNA mạch kép có kích thước ở cả 2 mạch đúng bằng đoạn gen mục tiêu là:","opts":["$64$.","$52$.","$58$.","$32$."],"ans":1,"exp":"Áp dụng công thức: $2^n - 2n = 2^6 - 2(6) = 64 - 12 = 52$ phân tử."},{"id":"MCQ-MO-016","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Operon Lac - Đề HSG Tỉnh","q":"Chủng <i>E. coli</i> lưỡng bội từng phần $I^+ P^- O^+ Z^+ Y^+ / F^\\prime I^- P^+ O^c Z^- Y^+$ nuôi trong môi trường KHÔNG có lactose sẽ tổng hợp được enzyme nào?","opts":["Chỉ tổng hợp được $\\beta$-galactosidase ($Z$).","Không tổng hợp enzyme nào.","Chỉ tổng hợp được permease ($Y$).","Tổng hợp cả $Z$ và $Y$."],"ans":2,"exp":"NST chính bị hỏng $P^-$ nên không phiên mã. Plasmid $F^\\prime$ có đột biến $O^c$ (phiên mã cơ định không phụ thuộc lactose) và có $Y^+$ bình thường nên chỉ tổng hợp permease."},{"id":"MCQ-MO-017","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Epigenetics - Đề HSG Tỉnh","q":"Sự biến đổi hóa học nào sau đây trên cấu trúc Chromatin thường dẫn đến việc GIÃN XOẮN nhiễm sắc thể (tạo Euchromatin) và kích hoạt mạnh quá trình phiên mã?","opts":["Acetyl hóa các gốc Lysine ở đuôi phân tử Histone nhờ enzyme Histone Acetyltransferase (HAT).","Methyl hóa mạnh các đảo CpG tại vùng Promoter của DNA.","Khử Acetyl (Deacetylation) phân tử Histone nhờ enzyme HDAC.","Bất hoạt NST bằng RNA <i>Xist</i>."],"ans":0,"exp":"Gắn nhóm Acetyl ($-COCH_3$) vào Lysine làm trung hòa điện tích dương của đuôi Histone, giảm lực hút tĩnh điện với khung xương âm điện của DNA, giúp NST giãn xoắn để RNA polymerase tiếp cận."},{"id":"MCQ-MO-018","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Enzyme Cắt giới hạn - Đề HSG Tỉnh","q":"Một phân tử DNA mạch thẳng dài $12\\text{ kb}$ được cắt hoàn toàn bằng enzyme <i>EcoRI</i> thu được 3 đoạn ($2\\text{ kb}, 4\\text{ kb}, 6\\text{ kb}$); nếu cắt bằng <i>HindIII</i> thu được 2 đoạn ($5\\text{ kb}, 7\\text{ kb}$); nếu cắt đồng thời bằng cả hai enzyme thu được 4 đoạn ($1\\text{ kb}, 2\\text{ kb}, 4\\text{ kb}, 5\\text{ kb}$). Số vị trí cắt của <i>EcoRI</i> và <i>HindIII</i> trên phân tử DNA này lần lượt là:","opts":["$2$ vị trí và $1$ vị trí.","$2$ vị trí và $2$ vị trí.","$3$ vị trí và $1$ vị trí.","$3$ vị trí và $2$ vị trí."],"ans":0,"exp":"Đối với DNA mạch thẳng, cắt tạo $m$ đoạn thì có $(m-1)$ vị trí cắt. Vậy <i>EcoRI</i> tạo 3 đoạn $\\rightarrow$ có $2$ vị trí cắt; <i>HindIII</i> tạo 2 đoạn $\\rightarrow$ có $1$ vị trí cắt (nằm trong đoạn $6\\text{ kb}$ của <i>EcoRI</i>, chia đoạn $6\\text{ kb}$ thành $5\\text{ kb} + 1\\text{ kb}$)."},{"id":"MCQ-MO-019","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Operon Tryptophan - Đề HSG Tỉnh","q":"Trong cơ chế điều hòa phiên mã suy giảm (Attenuation) ở vùng dẫn đầu ($trpL$) gồm 4 đoạn trình tự (1, 2, 3, 4) của Operon Trp ở <i>E. coli</i>, khi môi trường DƯ THỪA Tryptophan thì hiện tượng gì xảy ra?","opts":["Ribosome dịch mã nhanh qua đoạn 1 và che khuất đoạn 2, làm đoạn 3 bắt cặp với đoạn 4 tạo cấu trúc kẹp tóc kết thúc phiên mã sớm.","Tryptophan tách protein ức chế ra khỏi vùng Operator.","Ribosome dừng lại ở đoạn 1, giúp đoạn 2 bắt cặp với đoạn 3 để phiên mã tiếp tục.","Phức hợp CAP-cAMP gắn vào vùng Operator."],"ans":0,"exp":"Khi dư thừa Trp, tRNA$^{Trp}$ dồi dào giúp ribosome trượt nhanh qua 2 bộ ba Trp ở đoạn 1 và đè lên đoạn 2 $\\rightarrow$ đoạn 3 bắt cặp với đoạn 4 tạo kẹp tóc chấm dứt phiên mã ngay trước các gen cấu trúc."},{"id":"MCQ-MO-020","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Telomere & Telomerase - Đề HSG Tỉnh","q":"Tại sao ở các tế bào sinh dưỡng (soma) bình thường của người, đầu mút nhiễm sắc thể (Telomere) bị ngắn lại sau mỗi lần nhân đôi, trong khi tế bào mầm sinh dục và tế bào ung thư thì không?","opts":["Vì tế bào ung thư nhân đôi không cần đoạn mồi RNA.","Vì sau khi cắt bỏ đoạn mồi RNA ở đầu $5^\\prime$ của mạch mới, DNA polymerase không có đầu $3^\\prime-\\text{OH}$ để lấp chỗ trống; còn tế bào mầm và tế bào ung thư có enzyme Telomerase (mang khuôn RNA nội tại) kéo dài đầu $3^\\prime$ của mạch khuôn.","Vì tế bào soma không có enzyme DNA ligase.","Vì nhiễm sắc thể của tế bào ung thư có dạng mạch vòng."],"ans":1,"exp":"DNA polymerase chỉ tổng hợp theo chiều $5^\\prime \\rightarrow 3^\\prime$ khi có đầu $3^\\prime-\\text{OH}$ tự do. Khi đoạn mồi RNA ngoài cùng ở đầu $5^\\prime$ bị cắt bỏ, chỗ trống không được lấp đầy. Enzyme Telomerase hoạt động mạnh ở tế bào mầm và ung thư giúp bù đắp đoạn Telomere bị mất."},{"id":"MCQ-MO-021","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"CRISPR-Cas9 & Giải trình tự Sanger - Đề HSG Tỉnh","q":"Trong phương pháp giải trình tự DNA của Sanger sử dụng dideoxynucleotide ($ddNTP$), tại sao sự gắn một phân tử $ddATP$ vào mạch DNA đang tổng hợp lại làm chuỗi phản ứng dừng lại ngay lập tức tại vị trí đó?","opts":["Vì $ddATP$ không thể bắt cặp bổ sung với Thymine ($T$) trên mạch khuôn.","Vì $ddATP$ không có nhóm phosphate ở vị trí carbon $5^\\prime$.","Vì $ddATP$ làm biến tính enzyme DNA polymerase.","Vì đường của $ddATP$ bị mất nhóm hydroxyl ($-OH$) ở cả vị trí carbon $2^\\prime$ và $3^\\prime$ (chỉ có $-H$ ở vị trí $3^\\prime$), nên không thể hình thành liên kết phosphodiester với nucleotide tiếp theo."],"ans":3,"exp":"$ddNTP$ (2,3-dideoxynucleotide) thiếu nhóm $3^\\prime-\\text{OH}$ bắt buộc để tấn công ái nhân vào nhóm $5^\\prime$-phosphate của dNTP kế tiếp, nên quá trình kéo dài mạch dừng ngay lập tức."},{"id":"MCQ-MO-022","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Can thiệp RNA - miRNA/siRNA - Đề HSG Tỉnh","q":"Cơ chế điều hòa biểu hiện gen sau phiên mã bằng các phân tử RNA nhỏ (miRNA hoặc siRNA) kết hợp với phức hợp protein RISC ở tế bào nhân thực diễn ra như thế nào?","opts":["Gắn trực tiếp vào vùng Promoter của gen để kích thích RNA polymerase II.","Bắt cặp bổ sung với đoạn mRNA đích để cắt đứt (phân hủy) mRNA đích hoặc cản trở ribosome dịch mã trên mRNA đó.","Vận chuyển các amino acid tới ribosome.","Cắt bỏ các đoạn Intron ra khỏi tiền mRNA."],"ans":1,"exp":"Phức hợp RISC mang mạch đơn siRNA/miRNA dò tìm phân tử mRNA có trình tự bổ sung: nếu bắt cặp hoàn toàn sẽ cắt đứt mRNA đích; nếu bắt cặp một phần sẽ chặn đứng quá trình dịch mã của ribosome."},{"id":"MCQ-MO-023","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc DNA","q":"Theo mô hình cấu trúc xoắn kép DNA của Watson - Crick (dạng B-DNA), mỗi chu kỳ xoắn hoàn chỉnh dài $34\\text{ \\AA}$ chứa bao nhiêu cặp nucleotide và đường kính vòng xoắn là bao nhiêu?","opts":["$10$ cặp nucleotide; đường kính $20\\text{ \\AA}$.","$12$ cặp nucleotide; đường kính $10\\text{ \\AA}$.","$10$ cặp nucleotide; đường kính $34\\text{ \\AA}$.","$20$ cặp nucleotide; đường kính $34\\text{ \\AA}$."],"ans":0,"exp":"Mỗi chu kỳ xoắn B-DNA cao $34\\text{ \\AA}$ gồm 10 cặp nucleotide (mỗi bậc thang cao $3.4\\text{ \\AA}$), đường kính vòng xoắn đều đặn $20\\text{ \\AA}$."},{"id":"MCQ-MO-024","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc DNA","q":"Liên kết hóa học nối giữa đường Deoxyribose của nucleotide trước (tại vị trí $3'-\\text{C}$) với nhóm Phosphate của nucleotide kế tiếp (tại vị trí $5'-\\text{C}$) trên cùng một mạch đơn DNA là liên kết gì?","opts":["Liên kết Peptide.","Liên kết Hydrogen.","Liên kết Phosphodiester (liên kết cộng hóa trị bền vững).","Liên kết Glycoside giữa hai base đối diện."],"ans":2,"exp":"Khung đường - phosphate dọc mỗi mạch đơn polynucleotide được nối bằng liên kết cộng hóa trị phosphodiester $3'-5'$, tạo tính bền vững cơ học cho phân tử DNA."},{"id":"MCQ-MO-025","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc DNA","q":"Một phân tử DNA mạch kép ở sinh vật nhân sơ có chiều dài $5100\\text{ \\AA}$. Số chu kỳ xoắn và tổng số nucleotide của phân tử DNA này lần lượt là:","opts":["$300$ chu kỳ xoắn và $1500$ nucleotide.","$150$ chu kỳ xoắn và $1500$ nucleotide.","$150$ chu kỳ xoắn và $3000$ nucleotide.","$510$ chu kỳ xoắn và $3000$ nucleotide."],"ans":2,"exp":"$N = \\frac{2L}{3.4} = \\frac{2 \\times 5100}{3.4} = 3000\\text{ nu}$. Số chu kỳ xoắn $C = \\frac{L}{34} = \\frac{N}{20} = 150$."},{"id":"MCQ-MO-026","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc DNA","q":"Theo quy tắc bổ sung của Chargaff trong một phân tử DNA mạch kép bình thường, đẳng thức nào sau đây luôn luôn đúng?","opts":["$A = G$ và $T = C$.","$\\frac{A+T}{G+C} = 1$ ở mọi loài sinh vật.","$A + T = G + C$.","$A + G = T + C$ (tỉ lệ Purine / Pyrimidine $= 1$)."],"ans":3,"exp":"Do $A = T$ và $G = C$ nên tổng số base kích thước lớn (Purine: $A+G$) luôn bằng tổng số base kích thước nhỏ (Pyrimidine: $T+C$)."},{"id":"MCQ-MO-027","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc DNA","q":"Một đoạn gen có $120$ chu kỳ xoắn và có $G = 35\\%$ tổng số nucleotide. Số nucleotide từng loại của gen là:","opts":["$A = T = 720$; $G = C = 1680$.","$A = T = 360$; $G = C = 840$.","$A = T = 420$; $G = C = 780$.","$A = T = 840$; $G = C = 360$."],"ans":1,"exp":"$N = 120 \\times 20 = 2400$. $G = C = 35\\% \\times 2400 = 840$; $A = T = 15\\% \\times 2400 = 360$."},{"id":"MCQ-MO-028","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân đôi DNA","q":"Enzyme DNA polymerase chỉ có thể tổng hợp mạch DNA mới theo chiều duy nhất nào?","opts":["Chiều $3' \\rightarrow 5'$ trên cả hai mạch.","Chiều $5' \\rightarrow 3'$ (bổ sung nucleotide mới vào đầu $3'-\\text{OH}$ tự do).","Chiều $5' \\rightarrow 3'$ trên mạch dẫn đầu và chiều $3' \\rightarrow 5'$ trên mạch ra chậm.","Ngẫu nhiên theo cả hai chiều không cần đoạn mồi."],"ans":1,"exp":"Mọi DNA polymerase đã biết đều chỉ xúc tác gắn nhóm $5'$-phosphate của dNTP mới vào đầu $3'-\\text{OH}$ sẵn có, nên mạch mới luôn kéo dài theo hướng $5' \\rightarrow 3'$."},{"id":"MCQ-MO-029","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân đôi DNA","q":"Vì sao trên chạc chữ Y khi nhân đôi DNA, một mạch được tổng hợp liên tục còn mạch kia phải tổng hợp gián đoạn từng đoạn ngắn Okazaki?","opts":["Vì môi trường nội bào thiếu nucleotide tự do cho mạch thứ hai.","Vì enzyme Helicase chỉ tháo xoắn được một mạch khuôn.","Vì mạch gián đoạn được tổng hợp bằng RNA polymerase.","Vì hai mạch khuôn của DNA ngược chiều nhau ($3' \\rightarrow 5'$ và $5' \\rightarrow 3'$) trong khi enzyme DNA polymerase chỉ tổng hợp mạch mới theo chiều $5' \\rightarrow 3'$."],"ans":3,"exp":"Mạch khuôn có chiều $3' \\rightarrow 5'$ hướng vào chạc ba được tổng hợp liên tục; mạch khuôn còn lại ($5' \\rightarrow 3'$) buộc phải tổng hợp gián đoạn giật lùi theo chiều $5' \\rightarrow 3'$."},{"id":"MCQ-MO-030","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân đôi DNA","q":"Trong quá trình nhân đôi DNA ở vi khuẩn <i>E. coli</i>, enzyme nào đóng vai trò nối các đoạn Okazaki lại với nhau thành mạch DNA liên tục sau khi đoạn mồi RNA đã được thay thế bằng DNA?","opts":["Enzyme Helicase.","Enzyme DNA ligase.","Enzyme Primase.","Enzyme Topoisomerase."],"ans":1,"exp":"DNA polymerase I cắt bỏ mồi RNA và lấp khoảng trống bằng DNA, sau đó DNA ligase tạo liên kết phosphodiester nối liền vết đứt giữa các đoạn Okazaki."},{"id":"MCQ-MO-031","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân đôi DNA","q":"Nếu có 1 phân tử DNA ban đầu tiến hành nhân đôi liên tiếp $4$ lần bình thường trong tế bào, tổng số phân tử DNA con tạo thành và số phân tử DNA con có CẢ HAI mạch được tổng hợp hoàn toàn từ nguyên liệu mới của môi trường lần lượt là:","opts":["$16$ phân tử DNA con và $16$ phân tử có 2 mạch hoàn toàn mới.","$8$ phân tử DNA con và $6$ phân tử có 2 mạch hoàn toàn mới.","$16$ phân tử DNA con và $14$ phân tử có 2 mạch hoàn toàn mới.","$16$ phân tử DNA con và $2$ phân tử có 2 mạch hoàn toàn mới."],"ans":2,"exp":"Tổng DNA con $= 2^4 = 16$. Theo nguyên tắc bán bảo toàn, luôn có 2 phân tử giữ lại 1 mạch cũ, nên số phân tử hoàn toàn mới $= 2^4 - 2 = 14$."},{"id":"MCQ-MO-032","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân đôi DNA","q":"Trên một phân tử DNA của sinh vật nhân sơ có bao nhiêu điểm khởi đầu nhân đôi (Ori) so với một phân tử DNA nhiễm sắc thể của sinh vật nhân thực?","opts":["DNA nhân sơ chỉ có $1$ điểm Ori duy nhất; DNA nhân thực có rất nhiều điểm Ori hoạt động đồng thời.","DNA nhân sơ không cần điểm Ori.","DNA nhân sơ có hàng trăm điểm Ori; DNA nhân thực chỉ có $1$ điểm Ori.","Cả hai đều chỉ có $1$ điểm Ori."],"ans":0,"exp":"Hệ gen vi khuẩn nhỏ dạng vòng nên chỉ cần 1 điểm Ori (tạo 2 chạc chữ Y ngược chiều); DNA nhân thực rất dài nên cần hàng trăm đến hàng nghìn đơn vị tái bản để kịp tiến độ pha S."},{"id":"MCQ-MO-033","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Các loại RNA","q":"Loại phân tử RNA nào chiếm tỉ lệ lớn nhất (khoảng $75-80\\%$) trong tế bào chất và kết hợp với protein để tạo nên cấu trúc của Ribosome?","opts":["mRNA (RNA thông tin).","rRNA (RNA ribosome).","snRNA.","tRNA (RNA vận chuyển)."],"ans":1,"exp":"rRNA có tuổi thọ dài và khối lượng lớn, chiếm khoảng $80\\%$ tổng RNA tế bào, tạo khung cấu trúc và trung tâm xúc tác peptidyl transferase của ribosome."},{"id":"MCQ-MO-034","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Các loại RNA","q":"Trong 3 loại RNA chính (mRNA, tRNA, rRNA), loại nào đóng vai trò 'người phiên dịch' trực tiếp mang amino acid tới ribosome khớp với codon trên mRNA?","opts":["tiền mRNA.","rRNA tiểu phần lớn.","tRNA (mang bộ ba đối mã anticodon và đầu $3'-\\text{CCA}$ gắn đặc hiệu 1 amino acid).","mRNA mạch thẳng."],"ans":2,"exp":"tRNA có cấu trúc gấp cuộn 3 thùy (cỏ 3 lá), một đầu mang bộ ba đối mã (anticodon) khớp bổ sung với codon trên mRNA, đầu $3'$ mang amino acid tương ứng."},{"id":"MCQ-MO-035","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phiên mã","q":"Trong quá trình phiên mã tổng hợp phân tử RNA, enzyme RNA polymerase trượt dọc theo mạch khuôn của gen theo chiều nào và tổng hợp mạch RNA mới theo chiều nào?","opts":["Tổng hợp RNA cần đoạn mồi RNA do Primase tạo ra trước.","Trượt trên mạch gốc theo chiều $3' \\rightarrow 5'$ và tổng hợp mạch RNA theo chiều $5' \\rightarrow 3'$.","Trượt đồng thời trên cả hai mạch của gen.","Trượt trên mạch gốc theo chiều $5' \\rightarrow 3'$ và tổng hợp mạch RNA theo chiều $3' \\rightarrow 5'$."],"ans":1,"exp":"RNA polymerase tự khởi đầu tổng hợp RNA không cần mồi, đọc khuôn DNA theo chiều $3' \\rightarrow 5'$ để kéo dài mạch RNA theo chiều $5' \\rightarrow 3'$."},{"id":"MCQ-MO-036","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phiên mã","q":"Điểm khác biệt cơ bản của phân tử mRNA sơ khai mới phiên mã ở sinh vật nhân thực so với mRNA ở vi khuẩn (nhân sơ) là gì?","opts":["mRNA nhân thực chứa base Thymine thay cho Uracil.","mRNA sơ khai ở nhân thực chứa các đoạn Exon xen kẽ Intron nên phải cắt bỏ Intron, nối Exon và gắn mũ $5'$, đuôi Poly-A trước khi dịch mã.","mRNA nhân thực được dịch mã đồng thời ngay trong nhân khi đang phiên mã dở.","mRNA ở nhân sơ có rất nhiều đoạn Intron cần cắt bỏ."],"ans":1,"exp":"Ở nhân sơ, gen không phân mảnh nên mRNA phiên mã xong được ribosome bám dịch mã ngay lập tức; ở nhân thực, tiền mRNA phải qua xử lý trong nhân rồi mới xuất ra bào tương."},{"id":"MCQ-MO-037","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phiên mã","q":"Một đoạn mạch khuôn của gen có trình tự nucleotide là $3'-\\text{TAC GGT CAA ACT}-5'$. Trình tự phân tử mRNA được phiên mã từ đoạn mạch khuôn này là:","opts":["$5'-\\text{AUG CCA GUU UGA}-3'$.","$5'-\\text{UAC GGU CAA ACU}-3'$.","$5'-\\text{ATG CCA GTT TGA}-3'$.","$3'-\\text{AUG CCA GUU UGA}-5'$."],"ans":0,"exp":"Theo nguyên tắc bổ sung ($A-U, T-A, G-C, C-G$) và chiều ngược lại: $3'-\\text{TAC GGT CAA ACT}-5'$ phiên mã thành $5'-\\text{AUG CCA GUU UGA}-3'$."},{"id":"MCQ-MO-038","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Mã di truyền","q":"Trong 64 bộ ba (codon) của mã di truyền chuẩn trên mRNA, có bao nhiêu bộ ba mã hóa amino acid và bao nhiêu bộ ba kết thúc dịch mã?","opts":["$20$ bộ ba mã hóa amino acid và $44$ bộ ba kết thúc.","$60$ bộ ba mã hóa amino acid và $4$ bộ ba kết thúc.","$61$ bộ ba mã hóa amino acid và $3$ bộ ba kết thúc ($5'\\text{UAA}3'$, $5'\\text{UAG}3'$, $5'\\text{UGA}3'$).","$64$ bộ ba đều mã hóa amino acid."],"ans":2,"exp":"Có 3 codon kết thúc (stop codon) không mã hóa amino acid nào là $\\text{UAA, UAG, UGA}$; 61 codon còn lại mã hóa cho 20 loại amino acid."},{"id":"MCQ-MO-039","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Mã di truyền","q":"Đặc điểm 'nhiều bộ ba khác nhau có thể cùng mã hóa cho một loại amino acid' (ví dụ $\\text{GGU, GGC, GGA, GGG}$ đều mã hóa Glycine) phản ánh tính chất nào của mã di truyền?","opts":["Tính thoái hóa (Degeneracy).","Tính đặc hiệu.","Tính gối đầu.","Tính phổ biến."],"ans":0,"exp":"Trừ Methionine ($\\text{AUG}$) và Tryptophan ($\\text{UGG}$) chỉ có 1 bộ ba, 18 amino acid còn lại đều có từ 2 đến 6 bộ ba mã hóa — gọi là tính thoái hóa."},{"id":"MCQ-MO-040","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Mã di truyền","q":"Hầu hết các loài sinh vật từ vi khuẩn, thực vật đến động vật và con người đều sử dụng chung một bộ mã di truyền (trừ một vài ngoại lệ nhỏ ở ti thể). Điều này chứng minh điều gì?","opts":["Tính phổ biến (thống nhất) của mã di truyền và nguồn gốc tiến hóa chung của sinh giới.","Mọi loài sinh vật có trình tự DNA giống hệt nhau.","Mã di truyền có tính đặc hiệu tuyệt đối.","Các loài không có khả năng đột biến gen."],"ans":0,"exp":"Tính phổ biến của bảng mã di truyền là bằng chứng sinh học phân tử quan trọng khẳng định mọi sinh vật đều bắt nguồn từ tổ tiên chung cổ đại."},{"id":"MCQ-MO-041","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Dịch mã","q":"Trong quá trình dịch mã tổng hợp chuỗi polypeptide, ở sinh vật nhân sơ, bộ ba mở đầu $5'\\text{AUG}3'$ mã hóa cho amino acid mở đầu nào, còn ở sinh vật nhân thực là amino acid nào?","opts":["Ở cả hai đều là Alanine.","Ở nhân sơ là Formylmethionine (fMet); ở nhân thực là Methionine (Met).","Ở nhân sơ là Leucine; ở nhân thực là Formylmethionine.","Ở nhân sơ là Methionine; ở nhân thực là Valine."],"ans":1,"exp":"Bộ ba khởi đầu $\\text{AUG}$ ở vi khuẩn đưa fMet vào vị trí đầu chuỗi, còn ở sinh vật nhân thực và cổ khuẩn đưa Met thường vào vị trí đầu chuỗi."},{"id":"MCQ-MO-042","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Dịch mã","q":"Một phân tử mRNA trưởng thành có chiều dài $4080\\text{ \\AA}$ chứa vùng mã hóa liên tục từ bộ ba mở đầu đến bộ ba kết thúc. Có $6$ ribosome cùng trượt qua phân tử mRNA này mỗi ribosome 1 lần. Tổng số phân tử nước được giải phóng khi hình thành các liên kết peptide trong quá trình này là:","opts":["$2388$ phân tử nước.","$2400$ phân tử nước.","$398$ phân tử nước.","$2394$ phân tử nước."],"ans":0,"exp":"$rN = \\frac{4080}{3.4} = 1200$ ribonu $\\Rightarrow$ Số bộ ba $= 400$. Mỗi chuỗi polypeptide cần $(\\frac{rN}{3} - 1) = 399$ aa, tạo $399 - 1 = 398$ liên kết peptide $= 398$ phân tử $H_2O$. Với 6 ribosome: $6 \\times 398 = 2388$."},{"id":"MCQ-MO-043","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Dịch mã","q":"Sự gắn nhiều ribosome cùng trượt nối tiếp nhau trên một phân tử mRNA (tạo cấu trúc Polyribosome / Polysome) mang lại ý nghĩa sinh học trực tiếp gì cho tế bào?","opts":["Giúp tổng hợp nhiều loại protein hoàn toàn khác nhau từ 1 trình tự mRNA.","Giúp bảo vệ DNA khỏi enzyme cắt giới hạn.","Làm tăng nhanh hiệu suất tổng hợp nhiều phân tử protein cùng loại trong một khoảng thời gian ngắn.","Làm tăng tốc độ nhân đôi của ty thể."],"ans":2,"exp":"Polysome cho phép nhiều ribosome dịch mã song song trên cùng 1 bản sao mRNA, nhân lên nhanh chóng số lượng chuỗi polypeptide giống nhau."},{"id":"MCQ-MO-044","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Điều hòa gen","q":"Trong cấu trúc của một Operon Lac ở vi khuẩn <i>E. coli</i> theo mô hình của Jacob và Monod, trình tự nào sau đây KHÔNG nằm trong thành phần cấu tạo của Operon Lac?","opts":["Cụm gen cấu trúc $lacZ, lacY, lacA$.","Gen điều hòa $lacI$ (có promoter riêng nằm ở phía trước Operon).","Vùng vận hành $O$ (Operator).","Vùng khởi động $P$ (Promoter)."],"ans":1,"exp":"Một Operon chỉ gồm vùng điều hòa dùng chung ($P, O$) và nhóm gen cấu trúc ($Z, Y, A$). Gen điều hòa $lacI$ nằm độc lập phía trước với vùng khởi động riêng của nó."},{"id":"MCQ-MO-045","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Điều hòa gen","q":"Trong Operon Lac của <i>E. coli</i>, sản phẩm protein của 3 gen cấu trúc $lacZ, lacY, lacA$ có số lần phiên mã như thế nào trong môi trường có lactose?","opts":["Bằng nhau, vì cả 3 gen nằm nối tiếp nhau trên cùng một phân tử mRNA đa cistron được phiên mã từ một Promoter chung.","Gen $lacZ$ phiên mã nhiều gấp 10 lần gen $lacA$.","Chỉ có gen $lacZ$ được phiên mã khi có lactose.","Mỗi gen có một vùng Operator riêng biệt."],"ans":0,"exp":"RNA polymerase đọc liền mạch qua cả 3 gen $Z, Y, A$ tạo 1 bản sao mRNA polycistronic duy nhất nên số lượng bản sao mRNA của 3 gen là bằng nhau."},{"id":"MCQ-MO-046","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Điều hòa gen","q":"Ở sinh vật nhân thực, quá trình điều hòa hoạt động gen diễn ra phức tạp ở nhiều cấp độ hơn nhân sơ, trong đó cấp độ điều hòa nào giữ vai trò chủ yếu và tiết kiệm năng lượng nhất?","opts":["Chỉ điều hòa bằng Operon Lac.","Điều hòa trước phiên mã và điều hòa phiên mã (nhờ đóng mở chất nhiễm sắc và yếu tố phiên mã).","Phá hủy nhân tế bào sau mỗi lần dịch mã.","Chỉ điều hòa sau dịch mã."],"ans":1,"exp":"Kiểm soát ngay từ mức độ phiên mã (đóng mở cấu trúc NST, promoter, enhancer) giúp tế bào không tốn ATP và nguyên liệu tạo ra các bản sao mRNA không cần thiết."},{"id":"MCQ-MO-047","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến gen","q":"Dạng đột biến điểm nào sau đây thường gây hậu quả nghiêm trọng nhất làm thay đổi toàn bộ khung đọc từ vị trí đột biến đến cuối gen nếu xảy ra ngay phần đầu vùng mã hóa?","opts":["Mất $3$ cặp nucleotide nằm trọn vẹn trong một bộ ba.","Mất hoặc thêm $1$ cặp nucleotide (đột biến dịch khung).","Thay thế $1$ cặp nucleotide đồng nghĩa.","Thay thế $1$ cặp nucleotide ở vùng Intron."],"ans":1,"exp":"Mất hoặc thêm 1 (hoặc 2) cặp nu làm dịch chuyển khung đọc từng bộ ba phía sau vị trí đột biến, làm biến đổi hàng loạt amino acid hoặc tạo bộ ba kết thúc sớm."},{"id":"MCQ-MO-048","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến gen","q":"Bệnh thiếu máu hồng cầu hình liềm (Sickle cell anemia) ở người phát sinh do một đột biến điểm ở gen $\\beta$-globin làm thay thế một cặp $A-T$ thành $T-A$, biến bộ ba $5'\\text{GAG}3'$ (Glutamic acid) thành $5'\\text{GUG}3'$ (Valine) ở vị trí số 6. Đây là dạng đột biến nào?","opts":["Đột biến dịch khung.","Đột biến vô nghĩa (Nonsense mutation).","Đột biến đồng nghĩa (Silent mutation).","Đột biến sai nghĩa (Missense mutation)."],"ans":3,"exp":"Đột biến thay thế 1 cặp nu làm đổi bộ ba mã hóa amino acid này thành amino acid khác gọi là đột biến sai nghĩa."},{"id":"MCQ-MO-049","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến gen","q":"Nếu đột biến điểm thay thế 1 cặp nucleotide biến một bộ ba mã hóa amino acid (ví dụ $5'\\text{UAC}3'$ mã hóa Tyr) thành bộ ba kết thúc sớm ($5'\\text{UAA}3'$), dạng đột biến này được gọi là gì?","opts":["Đột biến vô nghĩa (Nonsense mutation).","Đột biến đồng nghĩa.","Đột biến sai nghĩa.","Đột biến mất đoạn NST."],"ans":0,"exp":"Đột biến biến codon mã hóa amino acid thành một trong 3 codon kết thúc (UAA, UAG, UGA) làm chuỗi polypeptide bị cắt ngắn sớm gọi là đột biến vô nghĩa."},{"id":"MCQ-MO-050","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến gen","q":"Tia tử ngoại (UV) với bước sóng khoảng $260\\text{ nm}$ tác động lên DNA thường gây ra dạng tổn thương đặc trưng nào dễ dẫn tới ung thư da (như ở bệnh nhân khô da sắc tố Xeroderma pigmentosum)?","opts":["Gắn thêm đuôi Poly-A vào giữa gen.","Tạo liên kết cộng hóa trị bất thường giữa hai base Thymine kế cận trên cùng một mạch (Dimer Thymine).","Đứt gãy đồng thời cả hai mạch của mọi nhiễm sắc thể.","Chuyển hóa toàn bộ Cytosine thành Adenine."],"ans":1,"exp":"Tia UV gây dimer hóa hai pyrimidine cạnh nhau (chủ yếu $T=T$), làm biến dạng xoắn kép DNA và cản trở nhân đôi, phiên mã."},{"id":"MCQ-MO-051","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến gen","q":"Một gen sau đột biến điểm có chiều dài không đổi, nhưng tổng số liên kết Hydrogen tăng thêm $1$ liên kết so với gen ban đầu. Dạng đột biến đã xảy ra là:","opts":["Thêm $1$ cặp $A-T$.","Thay thế $1$ cặp $G-C$ bằng $1$ cặp $A-T$.","Mất $1$ cặp $G-C$.","Thay thế $1$ cặp $A-T$ bằng $1$ cặp $G-C$."],"ans":3,"exp":"Chiều dài không đổi $\\Rightarrow$ thay thế nu. Tăng 1 liên kết H $\\Rightarrow$ đổi cặp $A-T$ (2 H) thành cặp $G-C$ (3 H)."},{"id":"MCQ-MO-052","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đột biến gen","q":"Thể đột biến là khái niệm dùng để chỉ:","opts":["Tác nhân vật lý hoặc hóa học gây ra đột biến.","Mọi cá thể mang alen đột biến lặn ở trạng thái dị hợp.","Bản thân sự biến đổi trình tự nucleotide trên phân tử DNA.","Cá thể mang đột biến đã được biểu hiện ra thành kiểu hình."],"ans":3,"exp":"Thể đột biến bắt buộc phải là cá thể mà đột biến (trội, hoặc lặn đồng hợp) đã biểu hiện ra kiểu hình; cá thể dị hợp mang alen lặn chưa biểu hiện chưa gọi là thể đột biến."},{"id":"MCQ-MO-053","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Công nghệ gen","q":"Trong kỹ thuật tạo DNA tái tổ hợp, hai loại enzyme bắt buộc phải sử dụng để cắt đoạn gen cần chuyển và vector plasmid tại cùng một vị trí nhận biết đặc hiệu, rồi nối chúng lại với nhau lần lượt là:","opts":["Amylase và Pepsin.","DNA polymerase và Catalase.","Enzyme cắt giới hạn (Restriction endonuclease / Restrictase) và Enzyme nối DNA ligase.","Helicase và RNA polymerase."],"ans":2,"exp":"Restrictase cắt tạo hai đầu dính (hoặc đầu tù) khớp nhau giữa DNA cho và plasmid, sau đó DNA ligase tạo liên kết phosphodiester hàn gắn thành DNA tái tổ hợp."},{"id":"MCQ-MO-054","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Công nghệ gen","q":"Khi thiết kế vector chuyển gen là Plasmid tái tổ hợp, việc gắn thêm một gen đánh dấu (ví dụ gen kháng kháng sinh Ampicillin $Amp^R$ hoặc gen $lacZ$) trên plasmid nhằm mục đích chính gì?","opts":["Để giúp plasmid nhân đôi nhanh gấp 100 lần.","Để sàng lọc, phát hiện và phân lập đúng những tế bào vi khuẩn đã nhận thành công plasmid tái tổ hợp.","Để tiêu diệt toàn bộ các tế bào đã nhận plasmid.","Để ngăn cản RNA polymerase phiên mã gen mục tiêu."],"ans":1,"exp":"Hiệu suất biến nạp plasmid vào vi khuẩn rất thấp; gen đánh dấu (selectable marker) cho phép nuôi cấy trên môi trường chứa kháng sinh để chỉ giữ lại tế bào chứa plasmid."},{"id":"MCQ-MO-055","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Công nghệ gen","q":"Bò sữa chuyển gen mang gen tổng hợp protein huyết thanh người (hoặc cừu mang gen tổng hợp $\\alpha$-1-antitrypsin người) thường được thiết kế để biểu hiện sản phẩm protein quý giá đó ở đâu để dễ thu hoạch và tinh sạch nhất?","opts":["Trong tế bào tủy xương.","Trong lông và sừng.","Trong tế bào não và dịch não tủy.","Trong sữa của động vật chuyển gen (nhờ gắn gen người dưới vùng Promoter của gen casein chỉ hoạt động ở tuyến vú)."],"ans":3,"exp":"Sử dụng promoter đặc hiệu tuyến vú (như $\\beta$-lactoglobulin hoặc casein) hướng protein tái tổ hợp tiết vào sữa với sản lượng lớn và dễ tách chiết mà không gây hại cho vật nuôi."},{"id":"MCQ-MO-056","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Công nghệ gen","q":"Giống lúa 'Gạo vàng' (Golden Rice) được tạo ra bằng công nghệ DNA tái tổ hợp mang lại giá trị dinh dưỡng nổi bật nào giúp phòng chống bệnh khô mắt và mù lòa ở trẻ em?","opts":["Nội nhũ hạt gạo có khả năng tổng hợp $\\beta$-carotene (tiền chất của Vitamin A).","Cây lúa có khả năng cố định trực tiếp $N_2$ không cần phân bón.","Hạt gạo không chứa bất kỳ tinh bột nào.","Hạt gạo chứa hàm lượng Insulin người rất cao."],"ans":0,"exp":"Lúa Golden Rice được chuyển tổ hợp gen (từ hoa thủy tiên/ngô và vi khuẩn <i>Pantoea</i>) giúp hoàn thiện con đường tổng hợp $\\beta$-carotene (Vitamin A) trong hạt gạo."},{"id":"MCQ-MO-057","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Kỹ thuật PCR","q":"Trong kỹ thuật nhân bản gen PCR (Polymerase Chain Reaction), vì sao người ta sử dụng enzyme Taq polymerase phân lập từ vi khuẩn suối nước nóng <i>Thermus aquaticus</i> thay cho DNA polymerase III của <i>E. coli</i>?","opts":["Vì Taq polymerase chịu được nhiệt độ cao ($94-95^\\circ\\text{C}$) ở bước biến tính tách hai mạch DNA mà không bị biến tính mất hoạt tính.","Vì DNA polymerase của <i>E. coli</i> hoạt động tốt nhất ở $100^\\circ\\text{C}$.","Vì Taq polymerase không cần đoạn mồi (primer) vẫn tổng hợp được DNA.","Vì Taq polymerase vừa phiên mã được RNA vừa tổng hợp được protein."],"ans":0,"exp":"Chu trình nhiệt của PCR phải nâng lên $94-95^\\circ\\text{C}$ để tách mạch kép DNA mỗi chu kỳ; Taq polymerase bền nhiệt giúp không phải bổ sung lại enzyme sau mỗi chu kỳ."},{"id":"MCQ-MO-058","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Kỹ thuật PCR","q":"Ba bước nhiệt độ tuần hoàn trong một chu kỳ chuẩn của phản ứng PCR (Biến tính $\\rightarrow$ Gắn mồi $\\rightarrow$ Kéo dài mạch) diễn ra theo thứ tự nhiệt độ tiêu chuẩn nào?","opts":["Gắn mồi ($37^\\circ\\text{C}$) $\\rightarrow$ Biến tính ($50^\\circ\\text{C}$) $\\rightarrow$ Kéo dài ($95^\\circ\\text{C}$).","Biến tính ($\\sim 94-95^\\circ\\text{C}$) $\\rightarrow$ Gắn mồi ($\\sim 50-65^\\circ\\text{C}$) $\\rightarrow$ Kéo dài ($\\sim 72^\\circ\\text{C}$).","Kéo dài ($95^\\circ\\text{C}$) $\\rightarrow$ Biến tính ($72^\\circ\\text{C}$) $\\rightarrow$ Gắn mồi ($55^\\circ\\text{C}$).","Cả ba bước đều giữ cố định ở $37^\\circ\\text{C}$."],"ans":1,"exp":"$95^\\circ\\text{C}$ phá vỡ liên kết H tách hai mạch; $50-65^\\circ\\text{C}$ cho hai mồi xuôi/ngược bắt cặp đặc hiệu; $72^\\circ\\text{C}$ là nhiệt độ tối ưu cho Taq polymerase kéo dài mạch mới."},{"id":"MCQ-MO-059","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Điện di DNA","q":"Trong kỹ thuật điện di trên gel Agarose, các đoạn DNA di chuyển về cực dương (Anode) dưới tác dụng của điện trường và tách rời theo kích thước dựa trên nguyên lý nào?","opts":["DNA mang điện tích DƯƠNG nên đi về cực dương; đoạn dài đi nhanh hơn đoạn ngắn.","Khung đường-phosphate của DNA mang điện tích ÂM thuần nên di chuyển về cực dương; đoạn DNA càng NGẮN thì di chuyển qua lỗ lưới gel càng NHANH.","Mọi đoạn DNA di chuyển cùng một vận tốc bất kể kích thước.","DNA di chuyển về cực âm nhờ các base nitơ mang điện dương."],"ans":1,"exp":"Nhờ nhóm phosphate mang điện âm ($PO_4^{3-}$), tỷ lệ điện tích/khối lượng của DNA là hằng định nên gel agarose sàng lọc phân tách DNA thuần túy theo chiều dài phân tử (bp/kb)."},{"id":"MCQ-MO-060","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc gen","q":"Một gen ở sinh vật nhân sơ có trình tự vùng mã hóa gồm $900$ cặp nucleotide (tính cả bộ ba mở đầu và bộ ba kết thúc). Khi gen này phiên mã và dịch mã bình thường, số bộ ba đối mã trên tRNA đã tham gia mang amino acid vào ribosome cho 1 chuỗi polypeptide là:","opts":["$298$.","$299$.","$300$.","$899$."],"ans":1,"exp":"900 cặp nu tương ứng 300 codon trên mRNA, trong đó 1 codon kết thúc không có tRNA khớp vào $\\Rightarrow$ cần $300 - 1 = 299$ lượt tRNA mang amino acid."},{"id":"MCQ-MO-061","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân đôi DNA","q":"Có $5$ phân tử DNA mẹ nhân đôi đồng thời một số lần bằng nhau tạo ra tổng cộng $160$ phân tử DNA con. Số lần nhân đôi của mỗi phân tử DNA ban đầu là:","opts":["$5$ lần.","$32$ lần.","$6$ lần.","$4$ lần."],"ans":0,"exp":"$5 \\times 2^k = 160 \\Rightarrow 2^k = 32 \\Rightarrow k = 5$ lần nhân đôi."},{"id":"MCQ-MO-062","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc DNA","q":"Trên một mạch đơn của đoạn phân tử DNA có $A_1 = 200$, $T_1 = 300$, $G_1 = 400$, $C_1 = 500$. Số lượng nucleotide loại $A$ và loại $G$ của cả phân tử DNA mạch kép này lần lượt là:","opts":["$A = 600$ và $G = 800$.","$A = 200$ và $G = 400$.","$A = 500$ và $G = 900$.","$A = 1000$ và $G = 1800$."],"ans":2,"exp":"Theo nguyên tắc bổ sung: $A = T = A_1 + T_1 = 200 + 300 = 500$; $G = C = G_1 + C_1 = 400 + 500 = 900$."},{"id":"MCQ-MO-063","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phiên mã","q":"Khi một gen cấu trúc tiến hành phiên mã $10$ lần liên tiếp thì số lượng phân tử mRNA tạo thành (chưa tính phân hủy) và số lần hai mạch của gen tách nhau ra lần lượt là:","opts":["$1024$ phân tử mRNA và $10$ lần tách xoắn.","$20$ phân tử mRNA và $10$ lần tách xoắn.","$10$ phân tử mRNA và $10$ lần tách xoắn cục bộ.","$10$ phân tử mRNA và $1$ lần tách xoắn duy nhất."],"ans":2,"exp":"Mỗi lần 1 phân tử RNA polymerase trượt qua gen phiên mã tạo 1 phân tử mRNA; trượt qua đâu tháo xoắn cục bộ đến đó và đóng xoắn lại ngay phía sau."},{"id":"MCQ-MO-064","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Biểu sinh học","q":"Khái niệm Di truyền Biểu sinh (Epigenetics) dùng để chỉ hiện tượng nào sau đây?","opts":["Sự nhân đôi độc lập của plasmid trong tế bào chất.","Những biến đổi có thể di truyền qua phân bào (hoặc thế hệ) làm thay đổi mức độ biểu hiện của gen mà KHÔNG làm thay đổi trình tự nucleotide của DNA.","Những đột biến mất hoặc thêm hàng loạt cặp nucleotide trong gen.","Sự trao đổi chéo giữa các nhiễm sắc thể tương đồng ở giảm phân I."],"ans":1,"exp":"Epigenetics nghiên cứu các cơ chế đánh dấu hóa học lên DNA (methyl hóa Cytosine) hoặc Histone (acetyl hóa, methyl hóa) và các RNA không mã hóa làm bật/tắt gen mà trình tự DNA giữ nguyên."},{"id":"MCQ-MO-065","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Công nghệ gen","q":"Trong quy trình giải trình tự DNA hoặc xác định dấu vân tay DNA (DNA fingerprinting) phục vụ pháp y và xác định huyết thống, kỹ thuật phân tích các đoạn lặp ngắn nối tiếp (STR - Short Tandem Repeats) thường kết hợp hai công cụ nào?","opts":["Nuôi cấy mô sẹo và gây đột biến 5-BU.","Lai tế bào soma và kính hiển vi quang học.","Phản ứng PCR khuếch đại các locus STR và Điện di mao quản/gel phân tách kích thước các băng DNA.","Chiết xuất Hemoglobin và đo độ hấp thụ quang."],"ans":2,"exp":"Số lần lặp lại tại mỗi locus STR có tính đa hình rất cao giữa các cá thể người; dùng PCR nhân bản cùng bộ mồi đặc hiệu rồi điện di phân tách độ dài băng sẽ cho hồ sơ DNA duy nhất (trừ sinh đôi cùng trứng)."},{"id":"MCQ-MO-066","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Điều hòa gen","q":"Trong cơ chế hoạt động của Operon Lac khi môi trường KHÔNG có cả Glucose lẫn Lactose (vi khuẩn bị đói hoàn toàn), trạng thái biểu hiện của các gen cấu trúc $lacZ, lacY, lacA$ là gì?","opts":["Protein ức chế bị phân hủy hoàn toàn bởi Glucose.","Phiên mã ở mức cực đại vì cAMP rất cao.","Không phiên mã (hoặc chỉ ở mức rò rỉ cực thấp) vì không có Allolactose để gỡ bỏ protein ức chế khỏi vùng Operator $O$.","Gen $lacI$ ngừng hoạt động vĩnh viễn."],"ans":2,"exp":"Dù nồng độ cAMP cao giúp phức hợp CAP-cAMP gắn vào Promoter, nhưng protein ức chế vẫn bám chặt vào Operator (do thiếu lactose/allolactose) nên chặn đứng RNA polymerase."},{"id":"MCQ-MO-067","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Dịch mã","q":"Trong bộ máy dịch mã (Ribosome hoàn chỉnh $70\\text{S}$ ở vi khuẩn hoặc $80\\text{S}$ ở nhân thực), ba vị trí bám dành cho các phân tử tRNA trên tiểu phần lớn theo đúng trình tự đi qua của tRNA là:","opts":["Vị trí P $\\rightarrow$ Vị trí E $\\rightarrow$ Vị trí A.","Vị trí E $\\rightarrow$ Vị trí P $\\rightarrow$ Vị trí A.","Vị trí A $\\rightarrow$ Vị trí E $\\rightarrow$ Vị trí P.","Vị trí A (Aminoacyl) $\\rightarrow$ Vị trí P (Peptidyl) $\\rightarrow$ Vị trí E (Exit)."],"ans":3,"exp":"tRNA mang aa mới đi vào vị trí A (trừ tRNA mở đầu vào thẳng P), chuyển chuỗi polypeptide ở vị trí P sang, trượt vào P rồi thoát ra ngoài qua vị trí E."},{"id":"MCQ-MO-068","topic":"molecular","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Sửa chữa DNA","q":"Hệ thống enzyme nào trực tiếp tham gia dò tìm và sửa chữa sai sót ngay trong quá trình nhân đôi DNA để hạ tỉ lệ đột biến ngẫu nhiên xuống mức chỉ khoảng $10^{-9} - 10^{-10}$ mỗi cặp base?","opts":["Enzyme Primase tự động cắt bỏ toàn bộ mạch mới.","Enzyme Reverse Transcriptase.","Enzyme Ribonuclease H.","Hoạt tính đọc sửa (Proofreading) $3' \\rightarrow 5'$ exonuclease của chính DNA polymerase kết hợp hệ thống sửa chữa ghép cặp sai (Mismatch repair - MMR) sau sao chép."],"ans":3,"exp":"Nếu DNA pol lắp nhầm nucleotide không đúng nguyên tắc bổ sung, hoạt tính $3'\\rightarrow 5'$ exonuclease cắt bỏ ngay lập tức, nâng độ chính xác thêm $100$ lần; hệ MMR kiểm tra nốt sai sót còn lại sau chạc ba."},{"id":"MCQ-MO-069","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cấu trúc DNA & Toán học","q":"Một gen có chiều dài $4080\\text{ \\AA}$ và tỉ lệ $\\frac{A+T}{G+C} = \\frac{2}{3}$. Gen nhân đôi liên tiếp $3$ lần. Số nucleotide loại $A$ và loại $G$ môi trường nội bào cần cung cấp cho quá trình nhân đôi này lần lượt là:","opts":["$A_{mt} = 1680$ và $G_{mt} = 2520$.","$A_{mt} = 3840$ và $G_{mt} = 5760$.","$A_{mt} = 5040$ và $G_{mt} = 3360$.","$A_{mt} = 3360$ và $G_{mt} = 5040$."],"ans":3,"exp":"$N = 2400$. Với $(A+T)/(G+C) = 2/3 \\Rightarrow A = T = 20\\% N = 480$, $G = C = 30\\% N = 720$. Nhân đôi 3 lần: $A_{mt} = 480(2^3 - 1) = 3360$; $G_{mt} = 720(2^3 - 1) = 5040$."},{"id":"MCQ-MO-070","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cấu trúc DNA & Toán học","q":"Một phân tử DNA mạch kép có tổng số liên kết Hydrogen là $3600$ và hiệu số giữa nucleotide loại $A$ với loại không bổ sung bằng $10\\%$ tổng số nucleotide của gen. Chiều dài của phân tử DNA này bằng bao nhiêu $\\text{\\AA}$?","opts":["$6120\\text{ \\AA}$.","$4080\\text{ \\AA}$.","$3060\\text{ \\AA}$.","$5100\\text{ \\AA}$."],"ans":3,"exp":"Ta có $A - G = 0.1N$ và $A + G = 0.5N \\Rightarrow A = 0.3N, G = 0.2N$. Suy ra $H = 2A + 3G = 2(0.3N) + 3(0.2N) = 1.2N = 3600 \\Rightarrow N = 3000\\text{ nu} \\Rightarrow L = \\frac{3000}{2} \\times 3.4 = 5100\\text{ \\AA}$."},{"id":"MCQ-MO-071","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phiên mã & Dịch mã","q":"Một gen có $N = 2400$ nucleotide. Trên mạch 1 của gen có $A_1 = 200, T_1 = 400, G_1 = 350, C_1 = 250$. Khi gen phiên mã $3$ lần lấy mạch 2 làm mạch khuôn, số ribonucleotide từng loại môi trường cung cấp lần lượt là:","opts":["$rA = 600; rU = 1200; rG = 1050; rC = 750$.","$rA = 200; rU = 400; rG = 350; rC = 250$.","$rA = 1200; rU = 600; rG = 750; rC = 1050$.","$rA = 600; rU = 1200; rG = 750; rC = 1050$."],"ans":0,"exp":"Lấy mạch 2 làm khuôn thì mạch mRNA có trình tự bổ sung mạch 2 nên giống trình tự mạch 1 (thay T bằng U): 1 bản sao có $rA = A_1 = 200, rU = T_1 = 400, rG = G_1 = 350, rC = C_1 = 250$. Phiên mã 3 lần nhân 3 tất cả."},{"id":"MCQ-MO-072","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đồng vị phóng xạ","q":"Nuôi $4$ phân tử DNA của vi khuẩn <i>E. coli</i> chỉ chứa đồng vị nặng $^{15}\\text{N}$ trong môi trường chỉ chứa $^{14}\\text{N}$ qua $3$ thế hệ. Số mạch đơn polynucleotide chứa $^{15}\\text{N}$ và số phân tử DNA hoàn toàn chỉ chứa $^{14}\\text{N}$ lần lượt là:","opts":["$8$ mạch $^{15}\\text{N}$ và $16$ phân tử DNA chỉ chứa $^{14}\\text{N}$.","$4$ mạch $^{15}\\text{N}$ và $28$ phân tử DNA chỉ chứa $^{14}\\text{N}$.","$8$ mạch $^{15}\\text{N}$ và $24$ phân tử DNA chỉ chứa $^{14}\\text{N}$.","$8$ mạch $^{15}\\text{N}$ và $32$ phân tử DNA chỉ chứa $^{14}\\text{N}$."],"ans":2,"exp":"4 phân tử DNA ban đầu có $8$ mạch $^{15}\\text{N}$ (không đổi qua nhân đôi). Tổng DNA con $= 4 \\times 2^3 = 32$ phân tử, trong đó có $8$ phân tử lai ($^{15}\\text{N}-^{14}\\text{N}$) và $32 - 8 = 24$ phân tử hoàn toàn $^{14}\\text{N}$."},{"id":"MCQ-MO-073","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến 5-BU & Base hiếm","q":"Một gen có chứa base Nitơ Guanine dạng hiếm ($G^*$) bắt cặp nhầm với Thymine ($T$) ngay ở lần nhân đôi thứ nhất. Sau tổng cộng $5$ lần nhân đôi liên tiếp trong môi trường bình thường, số phân tử gen con mang cặp đột biến $A-T$ hoàn chỉnh tạo thành là:","opts":["$16$ gen.","$31$ gen.","$15$ gen.","$7$ gen."],"ans":2,"exp":"Cặp $G^*-C$ ngay ở lần nhân đôi thứ nhất tạo $1$ mạch mang $T$; sau tổng cộng $k=5$ lần nhân đôi, số gen con mang cặp đột biến hoàn chỉnh $A-T$ sinh ra từ mạch mang $T$ đó là $2^{k-1} - 1 = 2^4 - 1 = 15$ gen."},{"id":"MCQ-MO-074","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến điểm & Amino acid","q":"Một gen bị đột biến mất $3$ cặp nucleotide kế tiếp nhau thuộc vùng mã hóa nhưng không làm xuất hiện bộ ba kết thúc sớm. Chuỗi polypeptide do gen đột biến tổng hợp có thể mất $1$ amino acid (nếu mất trọn 1 bộ ba) hoặc giảm $1$ amino acid và thay đổi tối đa bao nhiêu amino acid đứng liền kề?","opts":["Thay đổi $1$ amino acid mới (do ghép 2 phần của 2 bộ ba kế nhau thành 1 bộ ba mới) và mất $1$ amino acid.","Thay đổi toàn bộ các amino acid từ vị trí đột biến đến cuối chuỗi.","Không bao giờ có khả năng làm thay đổi bất kỳ amino acid nào khác.","Tăng thêm $1$ amino acid."],"ans":0,"exp":"Nếu mất 3 cặp nu vắt ngang ranh giới 2 bộ ba liên tiếp (ví dụ mất nu 2, 3 của bộ ba 1 và nu 1 của bộ ba 2), phần còn lại ghép thành 1 bộ ba mới tại vị trí đó (đổi tối đa 2 codon thành 1 codon mới) và khung đọc phía sau trở lại bình thường."},{"id":"MCQ-MO-075","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Mã di truyền & Wobble","q":"Theo giả thuyết Bắt cặp linh hoạt (Wobble) của Francis Crick, một phân tử tRNA duy nhất thường có thể nhận diện và giải mã chính xác nhiều codon đồng nghĩa khác nhau của cùng một amino acid. Sự bắt cặp linh hoạt này xảy ra ở vị trí nucleotide nào?","opts":["Vị trí base thứ $1$ (đầu $5'$) của codon trên mRNA.","Vị trí base thứ $2$ ở chính giữa codon và anticodon.","Vị trí base thứ $3$ (đầu $3'$) của codon trên mRNA bắt cặp với base thứ $1$ (đầu $5'$) của anticodon trên tRNA (thường có base hiếm Inosine $I$).","Vị trí đầu $3'-\\text{CCA}$ mang amino acid của tRNA."],"ans":2,"exp":"Hai base đầu của codon bắt cặp bổ sung nghiêm ngặt (Watson-Crick), còn base thứ 3 ở đầu $3'$ codon cho phép linh hoạt hình học với đầu $5'$ anticodon (ví dụ $I$ ghép được với $U, C, A$)."},{"id":"MCQ-MO-076","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Dịch mã & Enzyme","q":"Độ chính xác của quá trình dịch mã phụ thuộc vào 2 khâu: (1) gắn đúng amino acid vào tRNA tương ứng và (2) khớp đúng anticodon vào codon. Enzyme nào chịu trách nhiệm thực hiện khâu (1) bằng cách sử dụng ATP để gắn đúng 1 loại amino acid vào đúng tRNA?","opts":["DNA ligase.","Peptidyl transferase (là một ribozyme của rRNA 23S/28S).","RNA polymerase II.","Aminoacyl-tRNA synthetase (có $20$ loại enzyme đặc hiệu tương ứng cho $20$ loại amino acid)."],"ans":3,"exp":"Mỗi loại trong số 20 Aminoacyl-tRNA synthetase nhận diện chính xác cả amino acid đặc hiệu và các tRNA isoacceptor tương ứng của nó, tiêu tốn 1 ATP (thành AMP + 2Pi) để nạp tRNA."},{"id":"MCQ-MO-077","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Dịch mã & Kháng sinh","q":"Kháng sinh Erythromycin và Chloramphenicol ức chế chọn lọc quá trình tổng hợp protein ở vi khuẩn (gắn vào tiểu phần $50\\text{S}$ của ribosome $70\\text{S}$) nhưng ở liều điều trị lại không ức chế ribosome bào tương ($80\\text{S}$) của người. Tuy nhiên, nếu dùng liều quá cao kéo dài có thể gây tác dụng phụ độc cho tế bào người ở bào quan nào?","opts":["Nhân tế bào người.","Bộ máy Golgi.","Lưới nội chất hạt ở bào tương.","Ti thể của người, vì ti thể chứa ribosome loại $70\\text{S}$-like tương đồng về tiến hóa với vi khuẩn."],"ans":3,"exp":"Do nguồn gốc nội cộng sinh từ vi khuẩn, ribosome trong chất nền ti thể nhạy cảm với nhiều kháng sinh nhắm vào ribosome 70S (Chloramphenicol, Linezolid) nếu dùng liều cao."},{"id":"MCQ-MO-078","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phiên mã & Xử lý mRNA","q":"Trong cấu trúc mRNA trưởng thành của sinh vật nhân thực, vai trò chính của mũ $5'$-methylguanosine ($5'$-cap) và đuôi $3'$-Poly(A) là gì?","opts":["Biến mRNA thành phân tử DNA mạch kép.","Trực tiếp mã hóa các chuỗi Poly-Lysine ở cuối protein.","Giúp mRNA tích hợp ngược vào nhiễm sắc thể.","Bảo vệ mRNA khỏi bị các enzyme Exonuclease phân hủy, hỗ trợ xuất mRNA qua lỗ màng nhân và giúp ribosome nhận diện gắn vào để khởi đầu dịch mã."],"ans":3,"exp":"Đầu mũ $5'$ gắn với phức hợp CBC/eIF4E và đuôi Poly-A gắn với PABP tạo cấu trúc vòng kín khi dịch mã, đồng thời tăng tuổi thọ của mRNA trong bào tương."},{"id":"MCQ-MO-079","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cắt nối thay thế","q":"Hệ gen người chỉ có khoảng $20.000$ gen mã hóa protein nhưng cơ thể người lại tạo ra tới hàng trăm nghìn loại protein khác nhau. Cơ chế phân tử nào đóng góp lớn nhất vào sự đa dạng protein này ở cấp độ xử lý tiền mRNA?","opts":["Cắt nối thay thế (Alternative splicing) các Exon kết hợp sử dụng các điểm cắt nối hoặc promoter/poly-A thay thế.","Hệ gen người tự nhân đôi thêm hàng triệu bản sao mỗi ngày.","Mỗi bộ ba trên mRNA người mã hóa ngẫu nhiên 5 amino acid.","Sự tiếp hợp trao đổi đoạn giữa mRNA và rRNA."],"ans":0,"exp":"Hơn $90\\%$ gen đa exon ở người trải qua cắt nối thay thế (giữ/bỏ exon, giữ intron, dùng vị trí $5'/3'$ thay thế) để từ 1 gen tạo nhiều đồng phân protein (isoform) đặc hiệu theo từng mô."},{"id":"MCQ-MO-080","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Operon Lac","q":"Trong một môi trường nuôi cấy vi khuẩn <i>E. coli</i> kiểu dại chỉ có Lactose (hoàn toàn KHÔNG có Glucose), trạng thái của protein ức chế LacI và phức hợp hoạt hóa CAP-cAMP diễn ra như thế nào?","opts":["Protein ức chế bị bất hoạt nhưng cAMP rất thấp nên mức phiên mã rất yếu.","Protein ức chế bị bất hoạt bởi Allolactose (không bám vào Operator); nồng độ cAMP nội bào tăng cao tạo phức hợp CAP-cAMP gắn vào Promoter kích thích RNA polymerase phiên mã mạnh mẽ.","Protein ức chế bám chặt vào Operator và nồng độ cAMP bằng 0.","Cả Glucose và Allolactose cùng gắn vào RNA polymerase."],"ans":1,"exp":"Operon Lac chịu điều hòa kép: mở khóa âm tính (Allolactose gỡ LacI) và kích hoạt dương tính (thiếu Glucose $\\rightarrow$ cAMP tăng $\\rightarrow$ CAP-cAMP đẩy tốc độ phiên mã lên gấp 50 lần)."},{"id":"MCQ-MO-081","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Operon Lac","q":"Một chủng <i>E. coli</i> mang đột biến siêu ức chế $I^s$ (protein ức chế bị biến đổi vị trí gắn chất cảm ứng nên không thể gắn Allolactose, nhưng vẫn gắn rất chặt vào vùng Operator $O$). Chủng này khi nuôi trong môi trường có nhiều Lactose sẽ biểu hiện thế nào?","opts":["Trở thành chủng đột biến $O^c$.","Chỉ tổng hợp được Permease mà không tổng hợp $\\beta$-galactosidase.","Phiên mã liên tục các gen cấu trúc ngay cả khi không có Lactose.","Không thể phiên mã các gen $lacZ, lacY, lacA$ ngay cả khi có Lactose (tính trạng trội so với $I^+$ trong chủng lưỡng bội từng phần $I^s/F'I^+$)."],"ans":3,"exp":"Protein $I^s$ luôn khóa vùng Operator kể cả khi có Allolactose. Vì là protein khuếch tán (tác động <i>trans</i>), trong tế bào $I^s/I^+$ nó khóa cả hai vùng $O^+$ nên $I^s$ trội hơn $I^+$."},{"id":"MCQ-MO-082","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Operon Trp","q":"So với Operon Lac (hệ thống cảm ứng âm tính - bật khi có chất nền), Operon Tryptophan (Trp) ở <i>E. coli</i> thuộc kiểu điều hòa nào?","opts":["Hệ thống ức chế (Repressible operon): bình thường ở trạng thái BẬT để tổng hợp Tryptophan; khi môi trường dư thừa Tryptophan thì Tryptophan đóng vai trò đồng ức chế (Corepressor) gắn hoạt hóa protein ức chế bám vào vùng Operator để TẮT phiên mã.","Gen không bao giờ bị tắt kể cả khi dư thừa Tryptophan.","Operon Trp chỉ có ở tế bào động vật có vú.","Hệ thống cảm ứng dương tính: chỉ bật khi dư thừa Tryptophan."],"ans":0,"exp":"Các con đường đồng hóa sinh tổng hợp (như Trp) thường là operon ức chế: protein ức chế bình thường bất hoạt, chỉ khi có sản phẩm cuối (Trp) làm đồng ức chế mới bám vào $O$ tắt gen."},{"id":"MCQ-MO-083","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điều hòa nhân thực","q":"Ở sinh vật nhân thực, một trình tự DNA điều hòa gọi là Enhancer (vùng tăng cường) có thể nằm cách gen đích tới hàng chục nghìn cặp base (ở phía thượng nguồn, hạ nguồn hoặc thậm chí trong Intron) nhưng vẫn kích thích mạnh quá trình phiên mã của gen đó. Cơ chế nào cho phép khoảng cách xa như vậy?","opts":["Enhancer làm tan biến hoàn toàn màng nhân.","Các protein hoạt hóa phiên mã gắn vào Enhancer làm phân tử DNA uốn cong tạo vòng (DNA looping), tương tác trực tiếp với phức hợp Mediator và bộ máy RNA polymerase II tại vùng Promoter.","Enhancer tự dịch mã thành hormone di chuyển sang Promoter.","Enhancer cắt rời khỏi nhiễm sắc thể rồi trượt dọc đến nằm cạnh Promoter."],"ans":1,"exp":"Nhờ tính linh hoạt của chất nhiễm sắc và các phức hợp protein cầu nối (Mediator, Cohesin), sự uốn vòng DNA đưa các yếu tố gắn ở Enhancer tiếp xúc trực tiếp với Promoter."},{"id":"MCQ-MO-084","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Biểu sinh & Bất hoạt X","q":"Mèo tam thể (lông đốm đen, cam, trắng) hầu như chỉ có ở mèo cái ($XX$) mà rất hiếm gặp ở mèo đực bình thường ($XY$), ngoại trừ mèo đực bất thường $XXY$. Hiện tượng mảng lông loang lổ đen - cam xen kẽ ở mèo cái dị hợp $X^B X^b$ là kết quả trực tiếp của cơ chế biểu sinh nào?","opts":["Di truyền ngoài nhân qua ty thể.","Trao đổi chéo giữa nhiễm sắc thể X và Y.","Sự đột biến gen liên tục ở từng nang lông trưởng thành.","Sự bất hoạt ngẫu nhiên một trong hai nhiễm sắc thể X ở giai đoạn phôi sớm (tạo thể Barr), khiến mỗi dòng tế bào da chỉ biểu hiện alen màu đen ($X^B$) hoặc màu cam ($X^b$)."],"ans":3,"exp":"Theo giả thuyết Lyon, tại phôi nang sớm của động vật có vú cái ($XX$), mỗi tế bào bất hoạt ngẫu nhiên $X_{\\text{bố}}$ hoặc $X_{\\text{mẹ}}$ thông qua RNA <i>Xist</i> và methyl hóa DNA, duy trì trạng thái đó qua mọi lần nguyên phân."},{"id":"MCQ-MO-085","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Công nghệ gen & Enzyme cắt","q":"Enzyme cắt giới hạn <i>EcoRI</i> nhận biết trình tự đối xứng xuôi ngược (Palindrome) gồm 6 cặp nucleotide: $5'-\\text{GAATTC}-3'$ và cắt giữa $G$ và $A$ trên cả hai mạch. Đầu cắt tạo thành có đặc điểm gì?","opts":["Phá hủy hoàn toàn toàn bộ phân tử DNA thành từng nucleotide rời.","Chỉ cắt được trên phân tử RNA mạch đơn.","Tạo ra hai 'đầu tù' (blunt ends) phẳng lì.","Tạo ra hai 'đầu dính' (sticky ends) có phần nhô ra dài 4 nucleotide đơn là $5'-\\text{AATT}-3'$, dễ dàng bắt cặp bổ sung trở lại với bất kỳ đoạn DNA nào cũng được cắt bởi <i>EcoRI</i>."],"ans":3,"exp":"Cắt lệch giữa $G$ và $A$ trên hai mạch đối xứng tạo phần đầu mạch đơn $5'-\\text{AATT}$ đối xứng bổ sung lẫn nhau, giúp DNA ligase gắn ghép hiệu quả hơn đầu tù."},{"id":"MCQ-MO-086","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Công nghệ gen & Chuyển gen","q":"Để chuyển gen mong muốn (như gen $Bt$ kháng sâu) vào tế bào thực vật hai lá mầm (cây thuốc lá, cà chua, bông), phương pháp sinh học tự nhiên phổ biến nhất sử dụng 'kỹ sư di truyền tự nhiên' nào?","opts":["Vi khuẩn đất <i>Agrobacterium tumefaciens</i> mang plasmid Ti đã được vô hiệu hóa vùng gây khối u, giữ lại vùng biên T-DNA để chèn gen mục tiêu vào hệ gen cây.","Virus HIV phiên mã ngược.","Nấm men bánh mì <i>Saccharomyces</i>.","Thể thực khuẩn Phage $\\lambda$ gây tan vi khuẩn."],"ans":0,"exp":"<i>Agrobacterium tumefaciens</i> tự nhiên chuyển đoạn T-DNA từ plasmid Ti vào tích hợp vào nhiễm sắc thể tế bào thực vật; các nhà khoa học thay thế gen tạo u bằng gen mục tiêu."},{"id":"MCQ-MO-087","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Kỹ thuật PCR & Định lượng","q":"Từ $3$ phân tử DNA mạch kép ban đầu, thực hiện phản ứng PCR qua $5$ chu kỳ nhiệt chuẩn. Tổng số đoạn mồi (primer) mới đã tiêu thụ và số phân tử DNA mạch kép có 2 mạch đúng bằng kích thước vùng đích lần lượt là:","opts":["$93$ đoạn mồi và $66$ phân tử chuẩn.","$192$ đoạn mồi và $76$ phân tử chuẩn.","$186$ đoạn mồi và $96$ phân tử chuẩn.","$186$ đoạn mồi và $66$ phân tử chuẩn."],"ans":3,"exp":"Từ $a = 3$ phân tử ban đầu qua $n = 5$ chu kỳ: Số phân tử tạo thành $= 3 \\times 2^5 = 96$. Số mồi tiêu thụ $= 3 \\times 2(2^5 - 1) = 6 \\times 31 = 186$ mồi. Số phân tử có 2 mạch chuẩn $= 3 \\times (2^5 - 2 \\times 5) = 3 \\times 22 = 66$."},{"id":"MCQ-MO-088","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Giải trình tự & Điện di","q":"Trong phương pháp giải trình tự DNA Sanger thủ công dùng 4 ống nghiệm riêng chứa đủ dNTP và một lượng nhỏ chất kết thúc mạch có đánh dấu phóng xạ ($ddATP, ddTTP, ddGTP, ddCTP$). Khi đọc bản điện di từ ĐÁY gel (cực dương - đoạn ngắn nhất di chuyển nhanh nhất) lên ĐỈNH gel (đoạn dài nhất), ta thu được trình tự của mạch nào?","opts":["Trình tự phân tử mRNA ngược chiều.","Trình tự mạch DNA MỚI tổng hợp theo chiều từ đầu $5'$ (dưới đáy gel) đến đầu $3'$ (trên đỉnh gel).","Trình tự mạch khuôn theo chiều $5' \\rightarrow 3'$.","Trình tự mạch mới theo chiều từ $3'$ ở đáy lên $5'$ ở đỉnh."],"ans":1,"exp":"Mạch mới được kéo dài từ $5' \\rightarrow 3'$; các đoạn dừng lại sớm nhất (gần đầu $5'$ nhất) là ngắn nhất nên chạy xuống dưới cùng của bản gel."},{"id":"MCQ-MO-089","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"CRISPR-Cas9","q":"Hệ thống chỉnh sửa gen CRISPR-Cas9 hoạt động gồm 2 thành phần chính là enzyme cắt endonuclease Cas9 và phân tử RNA dẫn đường tổng hợp (sgRNA). Để phức hợp Cas9-sgRNA có thể nhận biết và cắt đứt sợi kép DNA tại vị trí đích, trình tự DNA mục tiêu bắt buộc phải có điều kiện gì nằm ngay kề bên?","opts":["Đuôi Poly-A dài $200$ nucleotide.","Trình tự PAM ngắn (Protospacer Adjacent Motif, ví dụ $5'-\\text{NGG}-3'$ đối với SpCas9) nằm ngay sát đầu $3'$ của đoạn trình tự đích.","Vùng Operator của Operon Lac.","Một đoạn Intron dài ít nhất $1000$ bp."],"ans":1,"exp":"Cas9 dò tìm trình tự PAM ($5'-\\text{NGG}-3'$) trên DNA trước khi tách mạch kép cho sgRNA bắt cặp kiểm tra tính bổ sung; nếu thiếu PAM, Cas9 hoàn toàn không cắt dù trình tự đích khớp 100% (giúp tự bảo vệ locus CRISPR ở vi khuẩn)."},{"id":"MCQ-MO-090","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"CRISPR-Cas9","q":"Sau khi phức hợp CRISPR-Cas9 tạo ra vết đứt sợi kép (DSB) chính xác tại gen đích trong tế bào nhân thực, nếu tế bào sửa chữa bằng cơ chế Nối đầu không tương đồng (NHEJ) mà không cấp khuôn DNA sửa chữa, kết quả phổ biến nhất thu được là gì?","opts":["Tạo ra các đột biến mất hoặc thêm ngẫu nhiên vài nucleotide (Indel) ngay tại điểm cắt, thường gây dịch khung làm BẤT HOẠT (Knock-out) chức năng của gen đó.","Nhân đôi nhiễm sắc thể đó lên $4n$.","Thay thế chính xác 1 cặp base theo mẫu thiết kế.","Chèn toàn bộ nhiễm sắc thể vi khuẩn vào gen."],"ans":0,"exp":"Tế bào có 2 đường sửa chữa DSB: NHEJ dễ mắc sai sót tạo Indel dùng để knock-out gen; còn HDR (tái tổ hợp tương đồng) dùng khuôn ngoại lai để knock-in hoặc chỉnh sửa chính xác đột biến."},{"id":"MCQ-MO-091","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phương pháp Lai phân tử","q":"Để xác định xem một gen X có mặt trong hệ gen hay không, xác định sự biểu hiện mức độ mRNA của gen X, và kiểm tra sự hiện diện của protein do gen X mã hóa, nhà nghiên cứu lần lượt sử dụng bộ ba kỹ thuật kinh điển nào?","opts":["Southern blot (kiểm tra DNA) $\\rightarrow$ Northern blot (kiểm tra RNA) $\\rightarrow$ Western blot (kiểm tra Protein).","Northern blot $\\rightarrow$ Western blot $\\rightarrow$ Southern blot.","PCR $\\rightarrow$ Southern blot $\\rightarrow$ Ly tâm phân đoạn.","Western blot $\\rightarrow$ Southern blot $\\rightarrow$ Northern blot."],"ans":0,"exp":"Quy tắc ghi nhớ chuẩn sinh học phân tử (SNoW DRoP): Southern = DNA; Northern = RNA; Western = Protein (dùng kháng thể đặc hiệu)."},{"id":"MCQ-MO-092","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến điểm & Protein","q":"Một gen cấu trúc ở sinh vật nhân sơ có trình tự vùng mã hóa trên mạch bổ sung (mạch không làm khuôn, $5' \\rightarrow 3'$) ở đoạn đầu là: $5'-\\text{ATG TTT GGC TAA}-3'$. Nếu xảy ra đột biến thay thế cặp nucleotide thứ 9 (cặp $C-G$) thành cặp $A-T$ (tức nucleotide thứ 9 trên mạch bổ sung đổi từ $C$ thành $A$), hậu quả đối với chuỗi polypeptide là gì? (Biết $5'\\text{UUU}3'=\\text{Phe}; 5'\\text{GGC}3'=\\text{Gly}; 5'\\text{GGA}3'=\\text{Gly}; 5'\\text{UAA}3'=\\text{Stop}$).","opts":["Không thay đổi thành phần amino acid nào của chuỗi polypeptide (đột biến đồng nghĩa) vì codon thứ 3 trên mRNA đổi từ $5'\\text{GGC}3'$ sang $5'\\text{GGA}3'$ đều mã hóa Glycine.","Xuất hiện bộ ba kết thúc sớm tại vị trí thứ 3.","Chuỗi polypeptide dài thêm 1 amino acid.","Đổi Glycine thành Phenylalanine."],"ans":0,"exp":"Mạch mRNA có trình tự giống mạch bổ sung (thay T bằng U): ban đầu $5'-\\text{AUG UUU GGC UAA}-3'$; đột biến ở vị trí thứ 9 đổi $C \\rightarrow A$ thành $5'-\\text{AUG UUU GGA UAA}-3'$. Cả $\\text{GGC}$ và $\\text{GGA}$ đều mã hóa Glycine."},{"id":"MCQ-MO-093","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến & Hóa chất","q":"Hóa chất Acridine orange là phân tử vòng phẳng có kích thước tương đương một cặp base, có thể xen kẽ vào giữa các cặp base xếp chồng trên DNA. Tác nhân này thường gây ra loại đột biến nào trong quá trình nhân đôi DNA?","opts":["Chỉ gây thay thế đồng chuyển $A-T \\leftrightarrow G-C$.","Tạo dimer Thymine trên cùng 1 mạch.","Gây đột biến đa bội toàn bộ bộ NST.","Đột biến thêm hoặc mất $1$ cặp nucleotide (gây đột biến dịch khung)."],"ans":3,"exp":"Thuốc nhuộm xen kẽ (Intercalating agents) như Acridine orange, Ethidium bromide làm biến dạng khoảng cách xoắn kép khiến DNA polymerase trượt mạch, chèn thêm hoặc bỏ sót nucleotide gây dịch khung."},{"id":"MCQ-MO-094","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến & Hóa chất","q":"Acid Nitrous ($\\text{HNO}_2$) gây khử amin oxy hóa (oxidative deamination) biến đổi Cytosine ($C$) thành Uracil ($U$), và biến đổi Adenine ($A$) thành Hypoxanthine ($H$, bắt cặp với $C$). Khi một cặp $G-C$ bị $\\text{HNO}_2$ làm biến đổi $C \\rightarrow U$ trước khi nhân đôi, sau $2$ lần nhân đôi tạo thành cặp đột biến ổn định nào?","opts":["Mất hoàn toàn cặp $G-C$.","Cặp $C-G$.","Cặp $A-T$ (tức đột biến thay thế $G-C \\rightarrow A-T$).","Thêm 1 cặp $A-T$."],"ans":2,"exp":"$G-C \\xrightarrow{\\text{HNO}_2} G-U$. Lần 1: mạch $U$ làm khuôn tạo $U-A$. Lần 2: mạch $A$ tạo cặp $A-T$ ổn định."},{"id":"MCQ-MO-095","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cấu trúc DNA & Phiên mã","q":"Giả sử trên một đoạn DNA kép dài $1500$ cặp nucleotide, mạch 1 có tỉ lệ $A_1 : T_1 : G_1 : C_1 = 1 : 2 : 3 : 4$. Tỉ lệ phần trăm số nucleotide loại $A$ và loại $G$ của cả đoạn DNA này lần lượt là:","opts":["$A = 15\\%$ và $G = 35\\%$.","$A = 10\\%$ và $G = 40\\%$.","$A = 20\\%$ và $G = 30\\%$.","$A = 30\\%$ và $G = 20\\%$."],"ans":0,"exp":"Trên mạch 1: $A_1 = 10\\%, T_1 = 20\\%, G_1 = 30\\%, C_1 = 40\\%$. Cả phân tử DNA có $\\%A = \\frac{\\%A_1 + \\%T_1}{2} = \\frac{10\\% + 20\\%}{2} = 15\\%$, suy ra $\\%G = 50\\% - 15\\% = 35\\%$."},{"id":"MCQ-MO-096","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tái bản DNA","q":"Trên một phân tử DNA dạng vòng của vi khuẩn <i>E. coli</i> có khối lượng phân tử $2.4 \\times 10^9\\text{ đvC}$ (biết 1 cặp nu nặng trung bình $600\\text{ đvC}$) và tốc độ gắn nucleotide của mỗi phức hợp DNA polymerase III là $1000\\text{ cặp nu/giây}$. Nếu tiến hành tái bản theo 2 hướng ngược chiều từ 1 điểm Ori duy nhất, thời gian tối thiểu để nhân đôi xong toàn bộ phân tử DNA này là bao nhiêu giây?","opts":["$8000$ giây.","$4000$ giây.","$2000$ giây.","$1000$ giây."],"ans":2,"exp":"Tổng số cặp nu $= \\frac{2.4 \\times 10^9}{600} = 4 \\times 10^6$ cặp nu. Do có 2 chạc chữ Y chạy ngược chiều đồng thời, tổng tốc độ là $2000$ cặp nu/s $\\Rightarrow t = \\frac{4 \\times 10^6}{2000} = 2000$ giây."},{"id":"MCQ-MO-097","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Dịch mã","q":"Một phân tử mRNA nhân tạo gồm các bộ ba lặp lại $5'-\\text{UGUGUGUGUGUG...}-3'$ mã hóa chuỗi polypeptide gồm Valine ($\\text{GUG}$) và Cysteine ($\\text{UGU}$) xen kẽ nhau. Nếu đột biến chèn thêm đúng $2$ nucleotide bất kỳ (không tạo bộ ba kết thúc) vào giữa mạch mRNA này thì đoạn mạch phía sau vị trí chèn sẽ dịch mã như thế nào?","opts":["Thay đổi hoàn toàn thành 2 loại amino acid mới từ điểm chèn đến cuối mạch.","Chỉ tổng hợp duy nhất 1 loại amino acid suốt đoạn sau.","Quay trở lại nhịp đọc luân phiên $2$ loại amino acid Valine và Cysteine giống ban đầu (chỉ thay đổi tối đa 1-2 amino acid ngay tại điểm chèn).","Không thể tiếp tục dịch mã."],"ans":2,"exp":"Do trình tự lặp lại chu kỳ $2$ nucleotide ($\\text{UG}$), bất kỳ sự chèn thêm $k$ nucleotide nào khác bội 2 hay làm lệch 1-2 nhịp cũng vẫn rơi vào 2 pha đọc $\\text{UGU}$ và $\\text{GUG}$ sau vùng chèn! Nếu chèn 2 nu (tổng cộng độ dài chèn 2), pha $6\\text{ nu}$ ($2\\text{ codon}$) bị trượt thành $\\text{UGU}-\\text{GUG}$ như cũ!"},{"id":"MCQ-MO-098","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Di truyền Biểu sinh","q":"Khảo sát một cặp song sinh cùng trứng (có bộ gen DNA giống hệt nhau $100\\%$) được nuôi dưỡng ở hai môi trường khác nhau từ nhỏ đến 50 tuổi. Kết quả phân tích cho thấy khi 5 tuổi mức độ methyl hóa DNA và acetyl hóa histone của họ gần như giống hệt nhau, nhưng đến năm 50 tuổi lại khác biệt rất lớn (dẫn đến một người mắc bệnh tiểu đường hoặc ung thư còn người kia thì không). Kết luận nào phù hợp nhất?","opts":["Các yếu tố môi trường, chế độ ăn và lối sống theo thời gian đã tạo ra các biến đổi biểu sinh (Epigenetic drift) khác nhau làm thay đổi hoạt động gen mà không đổi trình tự DNA.","Cặp song sinh cùng trứng thực chất có trình tự gen hoàn toàn khác nhau ngay từ khi thụ tinh.","Khi già đi, toàn bộ DNA trong nhân bị biến thành RNA.","Biểu sinh không bao giờ chịu ảnh hưởng của môi trường."],"ans":0,"exp":"Nghiên cứu kinh điển của Fraga và cộng sự trên các cặp song sinh đồng hợp tử chứng minh môi trường tích lũy các dấu ấn biểu sinh (methyl hóa DNA, sửa đổi histone) khác biệt theo tuổi tác."},{"id":"MCQ-MO-099","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phiên mã & Định lượng","q":"Trong tế bào nhân sơ <i>E. coli</i>, một gen dài $5100\\text{ \\AA}$ đang phiên mã. Tại một thời điểm, có $5$ phân tử RNA polymerase đang trượt nối tiếp nhau cách đều dọc theo gen với vận tốc $50\\text{ nucleotide/giây}$. Khoảng thời gian tối thiểu để gen tạo xong $1$ phân tử mRNA là bao nhiêu giây?","opts":["$30$ giây.","$60$ giây.","$150$ giây.","$15$ giây."],"ans":0,"exp":"Số nu trên 1 mạch khuôn của gen $= \\frac{5100}{3.4} = 1500$ nucleotide. Với tốc độ $50\\text{ nu/s}$, thời gian 1 RNA pol trượt hết chiều dài gen $= \\frac{1500}{50} = 30$ giây."},{"id":"MCQ-MO-100","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Công nghệ Gen & Plasmid","q":"Một nhà khoa học muốn chèn gen mã hóa Insulin người vào vị trí cắt <i>BamHI</i> nằm ngay bên trong gen kháng Tetracycline ($Tet^R$) của plasmid pBR322 (plasmid này vốn mang cả 2 gen kháng Ampicillin $Amp^R$ và kháng Tetracycline $Tet^R$). Sau khi biến nạp hỗn hợp vào vi khuẩn <i>E. coli</i> nhạy cảm kháng sinh, cần sàng lọc theo trình tự hai bước nào để chọn đúng khuẩn lạc chứa plasmid tái tổ hợp (đã nhận gen Insulin)?","opts":["Chọn khuẩn lạc chết trên cả môi trường chứa Ampicillin.","Nuôi trực tiếp trên môi trường chứa cả Ampicillin và Tetracycline rồi chọn khuẩn lạc mọc khỏe nhất.","Nuôi trên môi trường không chứa kháng sinh nào.","Bước 1: Nuôi trên đĩa thạch chứa Ampicillin (giữ lại vi khuẩn có plasmid); Bước 2: Chuyển mẫu khuẩn lạc sang đĩa thạch chứa Tetracycline và chọn những khuẩn lạc KHÔNG mọc được trên Tetracycline (bị chết do gen $Tet^R$ đã bị chèn đứt)."],"ans":3,"exp":"Kỹ thuật bất hoạt chèn (Insertional inactivation): chèn gen ngoại lai làm hỏng $Tet^R$ nhưng $Amp^R$ vẫn nguyên vẹn. Do đó tế bào chứa plasmid tái tổ hợp có kiểu hình $Amp^R Tet^S$ (kháng Ampicillin, nhạy cảm Tetracycline)."},{"id":"MCQ-MO-101","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Công nghệ Gen & Nhân thực","q":"Khi chuyển gen mã hóa protein kháng nguyên virus vào nấm men <i>Saccharomyces cerevisiae</i> (nhân thực) thay vì vi khuẩn <i>E. coli</i> (nhân sơ) để sản xuất vaccine viêm gan B tái tổ hợp, ưu thế vượt trội của nấm men so với vi khuẩn là gì?","opts":["Nấm men có thành tế bào bằng Peptidoglycan.","Nấm men không cần promoter vẫn phiên mã được mọi gen.","Nấm men là sinh vật nhân thực có bộ máy lưới nội chất và Golgi giúp thực hiện các biến đổi sau dịch mã (như gấp cuộn đúng, tạo cầu disulfide và gắn đường Glycosylation) tương đồng với tế bào động vật hơn <i>E. coli</i>.","Nấm men có tốc độ nhân đôi nhanh hơn <i>E. coli</i> gấp 10 lần."],"ans":2,"exp":"Nhiều protein người/virus đòi hỏi gắn gốc đường (glycosylation) và gấp cuộn phức tạp mới có tính kháng nguyên đúng; vi khuẩn thiếu bộ máy ER/Golgi nên thường tạo thể vùi không hoạt tính."},{"id":"MCQ-MO-102","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Sửa chữa DNA","q":"Bệnh nhân mắc hội chứng Di truyền khô da sắc tố (Xeroderma pigmentosum - XP) cực kỳ nhạy cảm với ánh sáng mặt trời và có nguy cơ ung thư da cao gấp hàng nghìn lần người bình thường. Khiếm khuyết phân tử gây bệnh XP nằm ở con đường nào?","opts":["Mất sắc tố Diệp lục trên biểu bì da.","Đột biến tăng hoạt động của enzyme Telomerase.","Đột biến mất chức năng một trong các enzyme của hệ thống Sửa chữa cắt bỏ Nucleotide (Nucleotide Excision Repair - NER), không loại bỏ được các dimer Thymine do tia UV tạo ra.","Mất hoàn toàn enzyme DNA ligase trong nguyên phân."],"ans":2,"exp":"Hệ thống NER nhận biết chỗ xoắn kép DNA bị phồng lệch do dimer Thymine hoặc chất gây ung thư cồng kềnh, cắt bỏ một đoạn oligonucleotide chứa sai sót (~12-30 nu) rồi tổng hợp lấp lại."},{"id":"MCQ-MO-103","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cấu trúc bộ gen","q":"Trong hệ gen của tế bào người bình thường, phần trình tự DNA mã hóa trực tiếp cho các phân tử protein (Exon mã hóa) thực tế chỉ chiếm khoảng bao nhiêu phần trăm tổng kích thước hệ gen nhân (~3.2 tỉ cặp base)?","opts":["Khoảng $1.5\\%$ (hơn $98\\%$ còn lại là Intron, trình tự điều hòa, gen giả, trình tự lặp lại và yếu tố di truyền vận động transposon).","Khoảng $50\\%$.","Đúng $75\\%$.","Khoảng $95\\%$."],"ans":0,"exp":"Dự án Giải mã Hệ gen Người (HGP) phát hiện chỉ khoảng $1.5\\%$ hệ gen mã hóa protein; phần lớn hệ gen là vùng không mã hóa đóng vai trò điều hòa biểu hiện gen, cấu trúc NST và tiến hóa."},{"id":"MCQ-MO-104","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Yếu tố di truyền vận động","q":"Các đoạn DNA có khả năng di chuyển từ vị trí này sang vị trí khác trong hệ gen ('gen nhảy' - Transposon) do Barbara McClintock phát hiện trên cây ngô chia làm 2 lớp chính. Điểm khác biệt giữa Retrotransposon (Lớp I) và DNA transposon (Lớp II) là gì?","opts":["DNA transposon luôn làm tăng số lượng bản sao qua trung gian mRNA.","Cả hai loại đều chỉ nằm trong màng ti thể.","Retrotransposon chỉ có ở vi khuẩn còn DNA transposon chỉ có ở virus.","Retrotransposon di chuyển theo cơ chế 'sao chép - dán' (copy and paste) qua trung gian bản sao RNA rồi phiên mã ngược thành DNA chèn vào vị trí mới; còn DNA transposon thường theo cơ chế 'cắt - dán' (cut and paste) nhờ enzyme Transposase."],"ans":3,"exp":"Retrotransposon (như LINE-1, Alu ở người) sử dụng RNA polymerase và Reverse Transcriptase nên nhân rộng số bản sao rất mạnh, chiếm tới hơn $40\\%$ kích thước hệ gen người."},{"id":"MCQ-MO-105","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đột biến & Dịch mã","q":"Một đoạn mRNA dài $510\\text{ nm}$ được dịch mã từ $5'$ đến $3'$. Đột biến xảy ra tại vùng mã hóa làm xuất hiện một bộ ba kết thúc sớm khiến chuỗi polypeptide hoàn chỉnh thu được chỉ còn đúng $198$ amino acid (đã cắt Met mở đầu). Bộ ba kết thúc đột biến nằm ở codon thứ bao nhiêu tính từ codon mở đầu (codon số 1)?","opts":["Codon thứ $199$.","Codon thứ $201$.","Codon thứ $200$.","Codon thứ $198$."],"ans":2,"exp":"Chuỗi hoàn chỉnh còn $198$ aa $\\Rightarrow$ trước khi cắt Met mở đầu có $199$ aa (tương ứng $199$ codon từ vị trí 1 đến 199) $\\Rightarrow$ Codon kết thúc nằm ngay ở vị trí thứ $200$."},{"id":"MCQ-MO-106","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phiên mã & Tương tác RNA","q":"Ở vi khuẩn, chuỗi trình tự giàu $G-C$ đối xứng xuôi ngược tạo cấu trúc 'kẹp tóc' (hairpin) theo sau bởi một dãy nhiều nucleotide $U$ (poly-U) ở đầu $3'$ của bản sao RNA mới tổng hợp đóng vai trò tín hiệu gì?","opts":["Tín hiệu khởi đầu tái bản DNA tại OriC.","Tín hiệu kết thúc phiên mã độc lập với yếu tố Rho (Rho-independent terminator): vòng kẹp tóc làm RNA polymerase khựng lại và đoạn ghép yếu $rU-dA$ dễ tách rời khỏi khuôn DNA.","Tín hiệu cắt bỏ đoạn Intron ở vi khuẩn.","Tín hiệu khởi đầu phiên mã tại hộp Pribnow $-10$."],"ans":1,"exp":"Cặp base $rU-dA$ chỉ có 2 liên kết H và lực xếp chồng rất yếu; khi kẹp tóc GC đẩy RNA polymerase dừng lại, bản sao RNA tự tách ra khỏi mạch khuôn DNA."},{"id":"MCQ-MO-107","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Điều hòa biểu hiện gen","q":"Nếu đưa nhân tạo một đoạn DNA bổ sung mã hóa vùng Promoter của một gen hoạt động mạnh vào trong tế bào với số lượng rất lớn bản sao (hiện tượng bẫy yếu tố phiên mã - Transcription factor decoy), điều gì sẽ xảy ra với gen nội sinh tương ứng trên nhiễm sắc thể?","opts":["Gen nội sinh tự động nhân đôi thêm nhiều bản sao.","Các yếu tố phiên mã chuyển sang dịch mã tạo protein.","Mức độ phiên mã của gen nội sinh tăng vọt gấp 100 lần.","Mức độ phiên mã của gen nội sinh bị GIẢM mạnh vì các đoạn DNA ngoại lai đã bắt giữ cạn kiệt các yếu tố phiên mã đặc hiệu (Transcription factors) trong nhân."],"ans":3,"exp":"Đây là nguyên lý liệu pháp Decoy oligonucleotide: cung cấp dư thừa trình tự gắn yếu tố phiên mã (như NF-$\\kappa$B) để hút hết yếu tố phiên mã tự do, ngăn chúng kích hoạt gen đích gây bệnh."},{"id":"MCQ-MO-108","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Công nghệ Gen & Thư viện gen","q":"So sánh giữa Thư viện hệ gen (Genomic library) và Thư viện cDNA (cDNA library) được tạo từ mô tuyến tụy của chuột, nhận định nào sau đây là chính xác?","opts":["Thư viện cDNA chứa đầy đủ tất cả các đoạn Intron và vùng dị nhiễm sắc tâm động.","Thư viện cDNA không cần dùng enzyme Reverse Transcriptase để xây dựng.","Thư viện hệ gen chỉ chứa những gen đang hoạt động ở mô gan.","Thư viện hệ gen giống nhau ở mọi mô (chứa cả Intron, Promoter và toàn bộ gen của loài); còn Thư viện cDNA chỉ chứa các trình tự Exon mã hóa của những gen ĐANG BIỂU HIỆN thành mRNA tại mô tụy lúc lấy mẫu."],"ans":3,"exp":"Thư viện cDNA phản ánh bản đồ biểu hiện gen đặc hiệu từng mô/giai đoạn (những gen không phiên mã ở tụy sẽ vắng mặt) và không chứa Intron hay vùng điều hòa không phiên mã."},{"id":"MCQ-MO-109","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tái bản DNA","q":"Một phân tử DNA nhân thực có $15$ đơn vị tái bản giống nhau, trên mỗi chạc chữ Y có $12$ đoạn Okazaki được tổng hợp trong pha S. Tổng số đoạn mồi RNA cần được tổng hợp để hoàn tất sao chép toàn bộ phân tử DNA này là bao nhiêu?","opts":["$30$ đoạn mồi.","$390$ đoạn mồi.","$195$ đoạn mồi.","$360$ đoạn mồi."],"ans":1,"exp":"$15$ đơn vị tái bản có $15 \\times 2 = 30$ chạc chữ Y. Mỗi chạc gồm 1 mạch liên tục ($1$ mồi) + 1 mạch gián đoạn ($12$ đoạn Okazaki $= 12$ mồi) $= 13$ mồi/chạc $\\Rightarrow$ Tổng $= 30 \\times 13 = 390$ đoạn mồi."},{"id":"MCQ-MO-110","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Mã di truyền & Đột biến","q":"Khi nghiên cứu một chủng nấm men đột biến mang một gen tRNA$^{\\text{Tyr}}$ bị biến đổi bộ ba đối mã từ $3'-\\text{AUG}-5'$ thành $3'-\\text{AUC}-5'$ nhưng vẫn gắn amino acid Tyrosine, chủng nấm men này có khả năng dịch mã vượt qua một đột biến vô nghĩa $5'-\\text{UAG}-3'$ trên mRNA của gen khác. Đột biến ở gen tRNA này gọi là gì?","opts":["Đột biến bất hoạt hoàn toàn ribosome.","Đột biến đồng nghĩa câm.","Đột biến ức chế vô nghĩa liên gen (Nonsense suppressor tRNA mutation).","Đột biến mất đoạn NST."],"ans":2,"exp":"Suppressor tRNA có anticodon đột biến khớp với codon kết thúc $\\text{UAG}$ và chèn Tyrosine thay vì dừng dịch mã, giúp khôi phục chức năng protein của gen bị đột biến vô nghĩa."},{"id":"MCQ-MO-111","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Mã di truyền nhân tạo","q":"Tổng hợp nhân tạo một phân tử mRNA từ hỗn hợp chứa $80\\%$ ribonucleotide loại $rA$ và $20\\%$ ribonucleotide loại $rG$ sắp xếp ngẫu nhiên. Tỉ lệ xuất hiện bộ ba mã hóa Lysine ($5'-\\text{AAA}-3'$) trên phân tử mRNA nhân tạo này theo lý thuyết là:","opts":["$64.0\\%$.","$51.2\\%$.","$80.0\\%$.","$32.0\\%$."],"ans":1,"exp":"Do các nucleotide gắn ngẫu nhiên độc lập, xác suất tạo bộ ba $5'-\\text{AAA}-3'$ là $P(\\text{AAA}) = 0.8 \\times 0.8 \\times 0.8 = 0.512 = 51.2\\%$."},{"id":"MCQ-MO-112","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Nhân đôi DNA & Enzyme","q":"Trong quá trình nhân đôi DNA ở <i>E. coli</i>, điểm khác biệt về vai trò giữa DNA polymerase III và DNA polymerase I là gì?","opts":["DNA polymerase III tổng hợp đoạn mồi RNA còn DNA polymerase I phân hủy DNA cũ.","DNA polymerase I tổng hợp mạch dẫn đầu còn DNA polymerase III chỉ nối các đoạn Okazaki.","DNA polymerase I có khả năng tháo xoắn thay cho Helicase.","DNA polymerase III tổng hợp kéo dài chủ yếu cả mạch dẫn đầu và các đoạn Okazaki với tốc độ cực cao; còn DNA polymerase I dùng hoạt tính $5'\\rightarrow 3'$ exonuclease để cắt bỏ các đoạn mồi RNA và dùng hoạt tính polymerase lấp chỗ trống bằng DNA."],"ans":3,"exp":"DNA pol III là enzyme sao chép chính (processivity cao); DNA pol I đặc trưng với hoạt tính exonuclease $5'\\rightarrow 3'$ dọn sạch đoạn mồi RNA và thay bằng dNTP."},{"id":"MCQ-MO-113","topic":"molecular","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cấu trúc gen & Liên kết hóa trị","q":"Một gen cấu trúc dài $3060\\text{ \\AA}$ tiến hành nhân đôi liên tiếp $3$ lần trong môi trường nội bào. Tổng số liên kết hóa trị (phosphodiester) mới được hình thành giữa các nucleotide trong quá trình nhân đôi của gen đó là bao nhiêu?","opts":["$12600$ liên kết.","$6293$ liên kết.","$14400$ liên kết.","$12586$ liên kết."],"ans":3,"exp":"Số nu của gen $N = \\frac{2 \\times 3060}{3.4} = 1800$ nu. Số liên kết hóa trị giữa các nu trong 1 gen kép $= 2(\\frac{N}{2} - 1) = N - 2 = 1798$. Sau 3 lần nhân đôi có $2^3 - 1 = 7$ gen tương đương tổng hợp mới $\\Rightarrow 1798 \\times 7 = 12586$ liên kết mới hình thành."},{"id":"MCQ-MO-114","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Operon Lac Lưỡng bội từng phần","q":"Xét các chủng <i>E. coli</i> lưỡng bội từng phần ($F'$) mang kiểu gen $I^s P^+ O^+ Z^+ Y^- / F'\\text{ }I^+ P^+ O^c Z^- Y^+$ (trong đó $I^s$ là đột biến siêu ức chế, $O^c$ là đột biến vùng vận hành làm mất khả năng gắn protein ức chế). Khi nuôi chủng này trong môi trường KHÔNG có Lactose, các enzyme $\\beta$-galactosidase ($Z$) và Permease ($Y$) được tổng hợp như thế nào?","opts":["Chỉ tổng hợp được $\\beta$-galactosidase ($Z$), không tổng hợp Permease ($Y$).","Tổng hợp cả hai enzyme $Z$ và $Y$ vì $O^c$ tác động <i>trans</i>.","Không tổng hợp $\\beta$-galactosidase ($Z$), chỉ tổng hợp liên tục Permease ($Y$) vì $O^c$ tác động theo kiểu <i>cis</i> lên bản sao mang $Y^+$, còn $I^s$ khóa chặt vùng $O^+$ trên nhiễm sắc thể chứa $Z^+$.","Không tổng hợp bất kỳ enzyme nào vì $I^s$ trội hoàn toàn trên cả 2 Operon."],"ans":2,"exp":"Vùng vận hành $O$ tác động <i>cis</i> (chỉ điều khiển các gen nằm liền kề trên cùng phân tử DNA): trên $F'$, $O^c$ không cho protein $I^s$ gắn vào nên phiên mã cơ định $Z^-$ (hỏng) và $Y^+$ (tạo Permease); trên NST chính, $I^s$ khóa chặt $O^+$ nên $Z^+$ tắt."},{"id":"MCQ-MO-115","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Operon Lac Lưỡng bội từng phần","q":"Chủng <i>E. coli</i> lưỡng bội từng phần có kiểu gen $I^- P^+ O^+ Z^+ Y^- / F'\\text{ }I^+ P^+ O^+ Z^- Y^+$ được nuôi trong hai điều kiện: (1) KHÔNG có Lactose và (2) CÓ Lactose (đều không có Glucose). Kết quả tổng hợp hai enzyme $Z$ và $Y$ trong 2 điều kiện lần lượt là:","opts":["Điều kiện (1): không tổng hợp $Z$ và $Y$; Điều kiện (2): tổng hợp cả hai enzyme $Z$ và $Y$ theo cảm ứng bình thường.","Điều kiện (1): tổng hợp cả $Z$ và $Y$; Điều kiện (2): không tổng hợp gì.","Trong cả hai điều kiện đều không tổng hợp enzyme nào.","Điều kiện (1): chỉ tổng hợp $Z$; Điều kiện (2): chỉ tổng hợp $Y$."],"ans":0,"exp":"Gen $I^+$ trên $F'$ tổng hợp protein ức chế bình thường khuếch tán (tác động <i>trans</i>) sang khóa cả hai vùng $O^+$ khi không có Lactose. Khi có Lactose, Allolactose giải phóng cả hai Operon nên $Z^+$ (NST) và $Y^+$ ($F'$) đều được tổng hợp."},{"id":"MCQ-MO-116","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Operon Lac & Đột biến CAP","q":"Một chủng vi khuẩn <i>E. coli</i> bị đột biến hỏng hoàn toàn gen mã hóa enzyme Adenylyl cyclase ($cya^-$), khiến tế bào hoàn toàn không thể tổng hợp được AMP vòng ($cAMP$). Khi nuôi chủng $cya^-$ này trong môi trường CHỈ có Lactose (không có Glucose), tốc độ phiên mã Operon Lac diễn ra như thế nào?","opts":["Phiên mã tăng vọt lên mức cực đại gấp 100 lần kiểu dại.","Phiên mã hoàn toàn bình thường giống hệt chủng kiểu dại $cya^+$.","Protein ức chế $LacI$ không thể gắn vào Operator nữa.","Mức độ phiên mã chỉ đạt rất thấp (gần như không đủ cho vi khuẩn sinh trưởng nhanh trên Lactose) dù Allolactose đã gỡ bỏ protein ức chế, vì thiếu phức hợp CAP-cAMP kích hoạt RNA polymerase."],"ans":3,"exp":"Promoter của Operon Lac có ái lực tự nhiên với RNA polymerase rất yếu; cần phức hợp CAP-cAMP trợ giúp mới phiên mã mạnh. Khi thiếu cAMP ($cya^-$) hoặc thiếu protein CAP ($crp^-$), Operon Lac không thể bật lên mức cao."},{"id":"MCQ-MO-117","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Operon Trp & Attenuation","q":"Trong cơ chế điều hòa phiên mã suy giảm (Attenuation) của Operon Tryptophan ở <i>E. coli</i>, nếu người ta gây đột biến xóa bỏ hoàn toàn hai bộ ba mã hóa Tryptophan liên tiếp ở đoạn trình tự số $1$ của vùng dẫn đầu $trpL$ (thay bằng hai bộ ba Glycine luôn dồi dào) hoặc đổi thành bộ ba kết thúc sớm ở đầu đoạn 1, điều gì xảy ra khi vi khuẩn sống trong môi trường THIẾU Tryptophan?","opts":["Ribosome không thể gắn vào đầu $5'$ của mRNA nữa.","Cả hai trường hợp đều khóa cứng protein ức chế TrpR.","Cả hai trường hợp đều làm tăng phiên mã gấp 10 lần khi dư Tryptophan.","Trường hợp thay bằng codon kết thúc sớm ở đầu đoạn 1: Ribosome dừng lại ở đoạn 1 làm đoạn 2 bắt cặp đoạn 3, nên Operon Trp phiên mã tiếp liên tục ngay cả khi DƯ THỪA Tryptophan; còn nếu thay bằng 2 codon Glycine thì ribosome đi thẳng qua đoạn 1 làm đoạn 3-4 đóng kẹp tóc kết thúc phiên mã ngay cả khi THIẾU Tryptophan."],"ans":3,"exp":"Vị trí dừng của ribosome quyết định cấu trúc thứ cấp kẹp tóc: dừng ở đoạn 1 (do thiếu Trp hoặc có Stop codon ở đoạn 1) giải phóng đoạn 2 ghép với đoạn 3 (chống kết thúc $\\rightarrow$ tiếp tục phiên mã); trượt qua đoạn 1 đè lên đoạn 2 buộc đoạn 3 ghép với đoạn 4 (kết thúc sớm)."},{"id":"MCQ-MO-118","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Enzyme Cắt giới hạn","q":"Một phân tử Plasmid DNA dạng VÒNG có kích thước tổng cộng $10\\text{ kb}$. Khi cắt hoàn toàn plasmid này bằng enzyme <i>EcoRI</i> thu được 2 đoạn ($3\\text{ kb}, 7\\text{ kb}$); khi cắt bằng enzyme <i>BamHI</i> thu được 2 đoạn ($4\\text{ kb}, 6\\text{ kb}$); khi cắt đồng thời cả <i>EcoRI</i> và <i>BamHI</i> thu được 4 đoạn có kích thước là $1\\text{ kb}, 2\\text{ kb}, 3\\text{ kb}, 4\\text{ kb}$. Hỏi số vị trí cắt của mỗi enzyme và khoảng cách ngắn nhất giữa hai vị trí cắt trên hai bên đoạn $3\\text{ kb}$ của <i>EcoRI</i> bị cắt bởi <i>BamHI</i> là bao nhiêu?","opts":["Cả hai vị trí của <i>BamHI</i> đều nằm trong đoạn $7\\text{ kb}$.","Mỗi enzyme có $2$ vị trí cắt; một vị trí <i>BamHI</i> cắt đoạn $3\\text{ kb}$ thành $1\\text{ kb} + 2\\text{ kb}$ và vị trí <i>BamHI</i> còn lại cắt đoạn $7\\text{ kb}$ thành $3\\text{ kb} + 4\\text{ kb}$.","Mỗi enzyme có $3$ vị trí cắt.","<i>EcoRI</i> có $1$ vị trí cắt và <i>BamHI</i> có $1$ vị trí cắt."],"ans":1,"exp":"Đối với DNA dạng VÒNG, $m$ vị trí cắt tạo đúng $m$ đoạn. Mỗi enzyme tạo 2 đoạn $\\Rightarrow$ mỗi enzyme có 2 vị trí cắt. Khi cắt kép: đoạn $3\\text{ kb}$ bị tách thành $1 + 2\\text{ kb}$ và đoạn $7\\text{ kb}$ bị tách thành $3 + 4\\text{ kb}$ (kiểm tra tổng 2 cung tròn: $1 + 3 = 4$ hoặc $2 + 4 = 6$, khớp hoàn toàn $4\\text{ kb}$ và $6\\text{ kb}$ của <i>BamHI</i>!)."},{"id":"MCQ-MO-119","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bản đồ Enzyme Cắt giới hạn","q":"Một phân tử DNA mạch THẲNG dài $15\\text{ kb}$ được cắt hoàn toàn bằng: <i>EcoRI</i> $\\rightarrow 2$ đoạn ($6\\text{ kb}, 9\\text{ kb}$); <i>HindIII</i> $\\rightarrow 2$ đoạn ($4\\text{ kb}, 11\\text{ kb}$); cắt kép cả hai enzyme $\\rightarrow 3$ đoạn ($2\\text{ kb}, 4\\text{ kb}, 9\\text{ kb}$) HOẶC nếu kết quả cắt kép lại cho $4\\text{ kb}, 5\\text{ kb}, 6\\text{ kb}$ thì sao? Với kết quả cắt kép thu được ($2\\text{ kb}, 4\\text{ kb}, 9\\text{ kb}$), thứ tự khoảng cách dọc từ một đầu đến đầu kia của đoạn DNA thẳng này là:","opts":["$4\\text{ kb} - 2\\text{ kb} - 9\\text{ kb}$ (vị trí <i>HindIII</i> ở mốc $4\\text{ kb}$, vị trí <i>EcoRI</i> ở mốc $6\\text{ kb}$).","$2\\text{ kb} - 9\\text{ kb} - 4\\text{ kb}$.","$4\\text{ kb} - 9\\text{ kb} - 2\\text{ kb}$.","$6\\text{ kb} - 4\\text{ kb} - 5\\text{ kb}$."],"ans":0,"exp":"Trong phép cắt kép ($2, 4, 9$), đoạn $9\\text{ kb}$ của <i>EcoRI</i> giữ nguyên, còn đoạn $6\\text{ kb}$ của <i>EcoRI</i> bị <i>HindIII</i> cắt thành $4 + 2\\text{ kb}$ sao cho $2 + 9 = 11\\text{ kb}$ (khớp đoạn $11\\text{ kb}$ của <i>HindIII</i>). Vậy thứ tự 3 đoạn liên tiếp là $4 - 2 - 9$."},{"id":"MCQ-MO-120","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Kỹ thuật PCR & Định lượng","q":"Trong kỹ thuật Real-time PCR định lượng (qPCR) dùng thuốc nhuộm huỳnh quang SYBR Green gắn vào DNA mạch kép, giả sử hiệu suất khuếch đại đạt $100\\%$ (tăng gấp đôi sau mỗi chu kỳ). Hai mẫu bệnh phẩm A và B chứa cùng một gen đích của virus, có ngưỡng phát hiện chu kỳ $C_t$ (Cycle threshold) lần lượt là $C_t(A) = 22$ và $C_t(B) = 28$. Lượng bản sao DNA virus ban đầu trong mẫu A lớn gấp bao nhiêu lần mẫu B?","opts":["Gấp $64$ lần ($2^6$).","Gấp $12$ lần.","Gấp $6$ lần.","Nhỏ hơn $64$ lần."],"ans":0,"exp":"Mẫu A chạm ngưỡng sớm hơn mẫu B đúng $\\Delta C_t = 28 - 22 = 6$ chu kỳ. Với hiệu suất $100\\%$, số lượng bản sao ban đầu của A gấp $2^{\\Delta C_t} = 2^6 = 64$ lần so với B."},{"id":"MCQ-MO-121","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Giải trình tự Sanger","q":"Khi giải trình tự một đoạn DNA ngắn bằng máy đọc huỳnh quang tự động Sanger dùng 4 màu đánh dấu cho 4 loại $ddNTP$ ($ddATP, ddTTP, ddGTP, ddCTP$), trên sắc ký đồ đọc từ mảnh ngắn nhất đến mảnh dài nhất thu được chuỗi tín hiệu: $5'-\\text{G C T A G T A C}-3'$. Trình tự của mạch DNA KHUÔN đã dùng trong phản ứng này là:","opts":["$5'-\\text{G C U A G U A C}-3'$.","$3'-\\text{C G A T C A T G}-5'$.","$3'-\\text{G C T A G T A C}-5'$.","$5'-\\text{C G A T C A T G}-3'$."],"ans":1,"exp":"Tín hiệu Sanger đọc được chính là mạch mới tổng hợp theo chiều $5' \\rightarrow 3'$. Theo nguyên tắc bổ sung ngược chiều, mạch khuôn có trình tự $3'-\\text{C G A T C A T G}-5'$."},{"id":"MCQ-MO-122","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Kỹ thuật PCR & Chọn mồi","q":"Cho một đoạn DNA mạch kép cần khuếch đại bằng PCR có trình tự mạch trên là:<br>$5'-\\text{ATGCCATGCA} \\dots [\\text{đoạn giữa 500 bp}] \\dots \\text{GCTTAGGCAT}-3'$.<br>Cặp mồi dài $10\\text{ nucleotide}$ phù hợp nhất (viết theo chiều chuẩn $5' \\rightarrow 3'$) để khuếch đại toàn bộ đoạn gen này là:","opts":["Mồi xuôi: $5'-\\text{ATGCCATGCA}-3'$ và Mồi ngược: $5'-\\text{ATGCCTAAGC}-3'$.","Mồi xuôi: $5'-\\text{ACGTACGGTA}-3'$ và Mồi ngược: $5'-\\text{ATGCCTAAGC}-3'$.","Mồi xuôi: $5'-\\text{ATGCCATGCA}-3'$ và Mồi ngược: $5'-\\text{GCTTAGGCAT}-3'$.","Mồi xuôi: $5'-\\text{TACGGTACGT}-3'$ và Mồi ngược: $5'-\\text{CGAATCCGTA}-3'$."],"ans":0,"exp":"Mồi xuôi khớp vào đầu $3'$ của mạch dưới nên có trình tự giống hệt đầu $5'$ của mạch trên ($5'-\\text{ATGCCATGCA}-3'$). Mồi ngược khớp vào đầu $3'$ của mạch trên ($...\\text{GCTTAGGCAT}-3'$) nên phải bổ sung ngược chiều: $5'-\\text{ATGCCTAAGC}-3'$."},{"id":"MCQ-MO-123","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Biểu sinh","q":"Ở động vật có vú, hiện tượng In dấu hệ gen (Genomic imprinting) diễn ra đối với cặp gen liên kết gần nhau trên NST số 11 (chuột là NST 7) gồm gen <i>Igf2</i> (chỉ biểu hiện bản sao từ BỐ) và gen <i>H19</i> (chỉ biểu hiện bản sao từ MẸ). Vùng kiểm soát in dấu (ICR) nằm giữa hai gen này đóng vai trò gì trong cơ chế cách ly (Insulator)?","opts":["Trên cả NST bố và NST mẹ, vùng ICR đều bị methyl hóa giống nhau.","Gen <i>Igf2</i> nằm trên nhiễm sắc thể Y nên mẹ không có.","Trên NST nhận từ MẸ, vùng ICR KHÔNG bị methyl hóa nên gắn được protein CTCF làm vật cách ly chặn vùng Enhancer kích thích <i>Igf2</i> (chỉ kích thích <i>H19</i>); trên NST nhận từ BỐ, vùng ICR BỊ methyl hóa nên CTCF không gắn được, cho phép Enhancer kích hoạt phiên mã <i>Igf2</i>.","Protein CTCF trực tiếp cắt bỏ gen <i>Igf2</i> khỏi NST của mẹ."],"ans":2,"exp":"Cơ chế cổ điển của imprinting cụm <i>Igf2/H19</i>: CTCF gắn vào ICR không methyl hóa ở bản sao mẹ đóng vai trò vách ngăn (insulator) chắn Enhancer; ở bản sao bố, methyl hóa DNA ngăn CTCF bám vào nên Enhancer vươn tới kích hoạt <i>Igf2</i>."},{"id":"MCQ-MO-124","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Biểu sinh","q":"Một đột biến mất hoàn toàn vùng ICR (chứa điểm gắn CTCF) trên NST nhận từ MẸ ở cụm gen <i>Igf2/H19</i> của chuột sẽ dẫn đến kiểu hình biểu hiện gen nào trên bản sao NST của mẹ đó?","opts":["Cả bản sao <i>Igf2</i> từ bố lẫn từ mẹ đều bị tắt hoàn toàn gây chuột siêu lùn.","Vùng Enhancer không còn bị protein CTCF chắn lại nên bản sao gen <i>Igf2</i> có nguồn gốc từ MẸ cũng được phiên mã biểu hiện (biểu hiện cả 2 bản sao bố và mẹ).","Gen <i>H19</i> tăng biểu hiện gấp 10 lần.","Chuột cái trở thành chuột đực."],"ans":1,"exp":"Mất ICR trên NST mẹ đồng nghĩa mất hàng rào cách ly CTCF, khiến Enhancer phía sau nhảy qua kích hoạt promoter của <i>Igf2</i> trên NST mẹ (gây hội chứng quá phát triển tương tự hội chứng Beckwith-Wiedemann ở người)."},{"id":"MCQ-MO-125","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Biểu sinh & Xist","q":"Trong quá trình bất hoạt một nhiễm sắc thể X ở tế bào phôi cái động vật có vú ($XX$), phân tử RNA không mã hóa dài <i>Xist</i> (X-inactive specific transcript) thực hiện chức năng như thế nào?","opts":["Xuất ra bào tương để dịch mã thành enzyme tiêu hủy toàn bộ NST X.","Di chuyển sang bất hoạt nhiễm sắc thể Y ở nam giới.","Phiên mã trực tiếp từ chính NST X sẽ bị bất hoạt, sau đó phân tử lncRNA <i>Xist</i> bao phủ dọc suốt chiều dài chính NST X đó và tuyển mộ phức hợp Polycomb (PRC2) đến methyl hóa Histone và DNA làm đóng xoắn chặt thành Thể Barr.","Bám lên tất cả các nhiễm sắc thể thường để bất hoạt chúng."],"ans":2,"exp":"RNA <i>Xist</i> hoạt động theo kiểu <i>cis</i> (chỉ phủ lên NST đã phiên mã ra nó), khởi phát chuỗi sửa đổi dị nhiễm sắc (H3K27me3, methyl hóa CpG) khóa im lặng hầu hết gen trên X bất hoạt."},{"id":"MCQ-MO-126","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đồng vị phóng xạ & Sao chép","q":"Nuôi $2$ tế bào vi khuẩn <i>E. coli</i> mà mỗi tế bào chỉ chứa một phân tử DNA vùng nhân mang toàn bộ đồng vị $^{14}\\text{N}$ trong môi trường chứa $^{15}\\text{N}$ qua $3$ thế hệ; sau đó tách lấy toàn bộ các phân tử DNA mang ít nhất 1 mạch $^{14}\\text{N}$ đem chuyển sang môi trường chỉ có $^{14}\\text{N}$ nhân đôi tiếp $2$ lần nữa. Kết thúc thí nghiệm, tổng số phân tử DNA hoàn toàn chỉ chứa $^{14}\\text{N}$ thu được là bao nhiêu?","opts":["$8$ phân tử.","$16$ phân tử.","$4$ phân tử.","$12$ phân tử."],"ans":3,"exp":"2 DNA ($^{14}\\text{N}$) nhân đôi 3 lần trong $^{15}\\text{N}$ tạo $16$ DNA, trong đó tách lấy riêng các phân tử có ít nhất 1 mạch $^{14}\\text{N}$ gồm đúng $4$ phân tử lai ($^{14}\\text{N}-^{15}\\text{N}$, mang tổng cộng $4$ mạch $^{14}\\text{N}$ và $4$ mạch $^{15}\\text{N}$). Chuyển 4 phân tử này sang $^{14}\\text{N}$ nhân đôi 2 lần tạo $4 \\times 2^2 = 16$ DNA. Trong đó có $4$ mạch $^{15}\\text{N}$ cố định (tạo 4 DNA lai), nên số DNA hoàn toàn $^{14}\\text{N} = 16 - 4 = 12$."},{"id":"MCQ-MO-127","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chạc tái bản & Telomere","q":"Nếu đột biến làm hỏng hoàn toàn hoạt tính của protein $\\text{TERT}$ (tiểu phần phiên mã ngược của enzyme Telomerase) trong tế bào gốc tạo máu của người, hệ quả dài hạn nào xảy ra qua nhiều lần phân chia tế bào?","opts":["Không ảnh hưởng gì vì DNA polymerase III tự tổng hợp được đầu $5'$.","DNA sợi kép chuyển thành DNA dạng vòng như vi khuẩn.","Tế bào gốc phân chia nhanh bất tử biến thành tế bào ung thư tức thì.","Các đầu mút Telomere bị rút ngắn dần sau mỗi chu kỳ sao chép cho tới khi đạt ngưỡng tới hạn, kích hoạt con đường phản ứng tổn thương DNA ($p53$) đẩy tế bào vào trạng thái lão hóa ngừng phân chia (Senescence) hoặc Apoptosis gây suy tủy xương."],"ans":3,"exp":"Telomerase là ribonucleoprotein gồm khuôn RNA ($\\text{TERC}$) và tiểu phần phiên mã ngược ($\\text{TERT}$). Thiếu Telomerase ở tế bào gốc (như hội chứng Dyskeratosis congenita) làm ngắn telomere sớm và suy kiệt tế bào gốc."},{"id":"MCQ-MO-128","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phiên mã Nhân thực","q":"Ở sinh vật nhân thực, ba loại enzyme RNA polymerase I, II và III đảm nhiệm các nhóm gen khác nhau. Độc tố nấm mũ tử thần $\\alpha$-Amanitin ở nồng độ thấp ức chế đặc hiệu hoàn toàn RNA polymerase II (trong khi Pol I kháng thuốc và Pol III chỉ nhạy cảm ở nồng độ rất cao). Khi xử lý tế bào người với nồng độ thấp $\\alpha$-Amanitin, quá trình tổng hợp phân tử nào bị ngừng lại đầu tiên?","opts":["Các phân tử rRNA $28\\text{S}, 18\\text{S}, 5.8\\text{S}$.","Các phân tử tRNA và rRNA $5\\text{S}$.","Các phân tử DNA trong pha S.","Toàn bộ tiền mRNA (mã hóa protein) và phần lớn miRNA/snRNA."],"ans":3,"exp":"Phân công chức năng chuẩn: Pol I tổng hợp pre-rRNA ($18\\text{S}, 5.8\\text{S}, 28\\text{S}$); Pol II tổng hợp tiền mRNA, snRNA, miRNA (cực nhạy với $\\alpha$-Amanitin); Pol III tổng hợp tRNA và rRNA $5\\text{S}$."},{"id":"MCQ-MO-129","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Xử lý tiền mRNA","q":"Trong quá trình cắt nối tiền mRNA (Splicing) bởi phức hợp Spliceosome để loại bỏ một đoạn Intron, hai phản ứng chuyển ester hóa liên tiếp tạo ra cấu trúc trung gian hình thòng lọng (Lariat) tại vị trí nucleotide đặc biệt nào nằm trong vùng điểm nhánh (Branch point) của Intron?","opts":["Nucleotide loại Thymine ($T$) ở đầu $3'$ của Exon 2.","Nucleotide loại Guanine ở đầu mũ $5'$.","Nucleotide loại Adenine ($A$) có nhóm $2'-\\text{OH}$ tự do tấn công vào đầu $5'$ ($\\text{GU}$) của Intron để khép vòng thòng lọng.","Một phân tử amino acid Methionine."],"ans":2,"exp":"Nhóm $2'-\\text{OH}$ của gốc Adenine bảo tồn tại branch point tấn công vào liên kết phosphodiester tại vị trí cắt $5'$ (trình tự $\\text{GU}$), tạo liên kết $2'-5'$ hình thòng lọng, giải phóng $3'-\\text{OH}$ của Exon 1 tấn công nối vào Exon 2."},{"id":"MCQ-MO-130","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Dịch mã & Điều hòa","q":"Ở tế bào người, khi nồng độ sắt ($\\text{Fe}^{2+}$) nội bào giảm xuống quá thấp, protein đáp ứng sắt IRP1/2 gắn vào cấu trúc kẹp tóc IRE (Iron-Responsive Element) trên hai loại mRNA khác nhau: (1) ở đầu $5'$-UTR của mRNA mã hóa Ferritin (protein dự trữ sắt) và (2) ở đầu $3'$-UTR của mRNA mã hóa Thụ thể Transferrin (protein nhập sắt vào tế bào). Sự gắn IRP này gây hiệu quả trái ngược nhau như thế nào?","opts":["IRP kích thích dự trữ nhiều sắt hơn vào Ferritin khi thiếu sắt.","IRP phân hủy ngay cả hai phân tử mRNA.","IRP kích thích dịch mã cả hai protein tăng gấp đôi.","IRP gắn vào $5'$-UTR của Ferritin làm CHẶN ribosome khởi đầu dịch mã (giảm tổng hợp Ferritin); còn IRP gắn vào $3'$-UTR của Thụ thể Transferrin giúp BẢO VỆ mRNA khỏi bị phân hủy (tăng tổng hợp thụ thể nhập sắt)."],"ans":3,"exp":"Đây là ví dụ kinh điển điều hòa sau phiên mã theo nhu cầu sinh lý: khi thiếu sắt, cần ngừng cất giữ sắt (tắt Ferritin) và tăng thu nhận sắt từ máu (bảo vệ mRNA thụ thể Transferrin)."},{"id":"MCQ-MO-131","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đột biến & Đọc sửa","q":"Một trình tự gen mã hóa ở vi khuẩn có $1500$ cặp nucleotide (gồm 1 codon mở đầu và 1 codon kết thúc). Trong quá trình phiên mã xảy ra sai sót ngẫu nhiên làm thay thế 1 ribonucleotide ở bộ ba thứ 50 (trong 500 bộ ba) trên <strong>một</strong> phân tử mRNA từ codon $5'-\\text{UGG}-3'$ (Trp) thành $5'-\\text{UGA}-3'$ (Stop). Tính chất biểu hiện và di truyền của sai sót này là gì?","opts":["Làm toàn bộ các phân tử mRNA được phiên mã tiếp theo từ gen đó đều mang bộ ba $\\text{UGA}$.","Chỉ tạo ra các chuỗi polypeptide bị cụt ngắn từ riêng phân tử mRNA bị lỗi đó (ảnh hưởng tức thời đến một số bản sao protein), nhưng KHÔNG di truyền cho thế hệ tế bào con vì trình tự DNA của gen không hề bị thay đổi.","Là đột biến điểm gây chết toàn bộ quần thể vi khuẩn.","Làm thay đổi vĩnh viễn trình tự DNA của tế bào vi khuẩn và di truyền cho toàn bộ thế hệ sau."],"ans":1,"exp":"Sai sót phiên mã trên một phân tử mRNA không phải đột biến gen; bản gốc DNA vẫn nguyên vẹn nên các phân tử mRNA phiên mã tiếp theo vẫn bình thường và không di truyền."},{"id":"MCQ-MO-132","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Công nghệ Gen & cDNA","q":"Một nhà sinh học phân lập gen mã hóa hormone tăng trưởng người (gồm 5 Exon và 4 Intron, dài tổng cộng $2.2\\text{ kb}$ trên NST, nhưng mRNA trưởng thành phần mã hóa chỉ dài $651$ nucleotide) để chuyển vào vi khuẩn <i>E. coli</i> sản xuất thuốc. Nếu người đó vô tình lấy thẳng đoạn DNA hệ gen $2.2\\text{ kb}$ (còn nguyên Intron) ghép sau Promoter của vi khuẩn rồi biến nạp vào <i>E. coli</i>, kết quả nào xảy ra?","opts":["<i>E. coli</i> từ chối phiên mã bất kỳ đoạn DNA nào có nguồn gốc từ người.","Hormone tạo ra có kích thước nhỏ hơn bình thường 4 lần.","<i>E. coli</i> tự động nhận biết và cắt bỏ hết 4 Intron tạo hormone chuẩn.","<i>E. coli</i> vẫn phiên mã qua các đoạn Intron nhưng vì không có Spliceosome cắt bỏ Intron nên dịch mã ra một chuỗi polypeptide sai lệch hoàn toàn (thường gặp bộ ba kết thúc sớm ngay trong Intron 1) và không có hoạt tính sinh học."],"ans":3,"exp":"Vi khuẩn không có cơ chế cắt nối spliceosome đối với intron nhân thực loại GT-AG, nên nó đọc liền cả trình tự intron vào khung dịch mã tạo protein vô nghĩa."},{"id":"MCQ-MO-133","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thí nghiệm Meselson - Stahl","q":"Nếu cơ chế nhân đôi DNA giả sử diễn ra theo kiểu <strong>Bảo toàn</strong> (Conservative: phân tử mẹ giữ nguyên 2 mạch cũ $^{15}\\text{N}-^{15}\\text{N}$, phân tử mới gồm toàn 2 mạch mới $^{14}\\text{N}-^{14}\\text{N}$) thay vì Bán bảo toàn, thì sau ĐÚNG $1$ thế hệ chuyển từ môi trường $^{15}\\text{N}$ sang $^{14}\\text{N}$ rồi đem ly tâm theo thang tỷ trọng CsCl, ta sẽ quan sát thấy kết quả băng DNA như thế nào?","opts":["Chỉ có một băng duy nhất nằm ở vị trí trung gian (lai $^{15}\\text{N}-^{14}\\text{N}$).","Xuất hiện HAI băng tách biệt rõ rệt: một băng nặng ($^{15}\\text{N}-^{15}\\text{N}$) và một băng nhẹ ($^{14}\\text{N}-^{14}\\text{N}$) với tỉ lệ bằng nhau, hoàn toàn KHÔNG có băng lai trung gian.","Có ba băng gồm nặng, trung gian và nhẹ.","Chỉ có một băng nhẹ duy nhất ($^{14}\\text{N}-^{14}\\text{N}$)."],"ans":1,"exp":"Thực tế thí nghiệm Meselson-Stahl sau thế hệ 1 chỉ cho DUY NHẤT 1 băng trung gian (bác bỏ mô hình Bảo toàn), và sau thế hệ 2 cho 1 băng trung gian + 1 băng nhẹ (bác bỏ mô hình Phân tán)."},{"id":"MCQ-MO-134","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Mã di truyền & Khởi đầu","q":"Ở sinh vật nhân thực, bộ ba $5'-\\text{AUG}-3'$ đầu tiên tính từ đầu $5'$ của mRNA thường được tiểu phần nhỏ ribosome ($40\\text{S}$) nhận biết làm điểm khởi đầu dịch mã (theo mô hình quét - Scanning model của Marilyn Kozak). Yếu tố trình tự nào bao quanh bộ ba $\\text{AUG}$ giúp ribosome nhận biết đây là bộ ba mở đầu tối ưu mà không trượt qua?","opts":["Hộp TATA nằm trong Intron 1.","Trình tự Shine-Dalgarno ($5'-\\text{AGGAGGU}-3'$) nằm cách $\\text{AUG}$ 10 nucleotide ở nhân sơ.","Trình tự đồng thuận Kozak (ví dụ $5'-\\text{GCCRCCAUGG}-3'$ với Purine tại $-3$ và Guanine tại $+4$).","Vùng Operator $lacO$."],"ans":2,"exp":"Ở vi khuẩn, rRNA $16\\text{S}$ bắt cặp trực tiếp vào trình tự Shine-Dalgarno (RBS) để định vị $\\text{AUG}$; ở nhân thực, ribosome gắn mũ $5'$ rồi quét xuôi dòng tìm $\\text{AUG}$ nằm trong ngữ cảnh trình tự Kozak."},{"id":"MCQ-MO-135","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phiên mã ngược & Telomerase","q":"Enzyme nào sau đây có bản chất là một loại enzyme Phiên mã ngược (RNA-dependent DNA polymerase) nhưng lại hoạt động tự nhiên ở tế bào mầm sinh dục bình thường của người (không phải do virus mang vào)?","opts":["Tiểu phần xúc tác $\\text{TERT}$ của phức hợp enzyme Telomerase (dùng khuôn RNA nội tại $\\text{TERC}$ để kéo dài đầu $3'$ sợi giàu G của Telomere).","Enzyme DNA ligase I.","DNA polymerase $\\delta$ tổng hợp mạch ra chậm.","RNA polymerase II."],"ans":0,"exp":"Telomerase mang sẵn phân tử khuôn RNA (TERC) bên trong phức hợp để tổng hợp đoạn lặp DNA ($5'-\\text{TTAGGG}-3'$ ở người), do đó hoạt tính sinh hóa của TERT chính là phiên mã ngược."},{"id":"MCQ-MO-136","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Can thiệp RNA (RNAi)","q":"Khi so sánh cơ chế tác động của hai loại RNA nhỏ điều hòa biểu hiện gen là $\\text{siRNA}$ (small interfering RNA) và $\\text{miRNA}$ (microRNA) ở tế bào động vật, sự khác biệt đặc trưng nhất giữa chúng là gì?","opts":["$\\text{miRNA}$ chỉ có ở vi khuẩn còn $\\text{siRNA}$ chỉ có ở người.","$\\text{siRNA}$ gắn vào Promoter của DNA còn $\\text{miRNA}$ gắn trực tiếp vào amino acid.","$\\text{siRNA}$ thường có nguồn gốc từ RNA sợi kép ngoại lai (hoặc virus) và bắt cặp bổ sung HOÀN TOÀN ($100\\%$) với mRNA đích để cắt đứt phân hủy nó; $\\text{miRNA}$ mã hóa từ gen nội sinh (tạo tiền chất dạng kẹp tóc) và thường bắt cặp KHÔNG hoàn toàn ở vùng $3'$-UTR để ức chế dịch mã hoặc làm bất ổn mRNA.","Cả hai đều kích thích tăng gấp đôi tốc độ dịch mã của mRNA đích."],"ans":2,"exp":"Cả miRNA và siRNA đều được cắt bởi enzyme Dicer và nạp vào phức hợp RISC (chứa protein Argonaute), nhưng mức độ bắt cặp bổ sung quyết định cắt trực tiếp (siRNA) hay kìm hãm dịch mã/khử đuôi poly-A (miRNA động vật)."},{"id":"MCQ-MO-137","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đột biến & Đọc khung","q":"Phân tích trình tự DNA của gen mã hóa một enzyme ở 3 chủng nấm men: Kiểu dại bình thường; Chủng đột biến M1 bị mất hoạt tính hoàn toàn; Chủng đột biến kép M1+M2 (tạo bằng cách gây thêm đột biến thứ 2 trên nền chủng M1) bất ngờ PHỤC HỒI phần lớn hoạt tính enzyme (dù có vài amino acid ở đoạn ngắn bị thay đổi). Tổ hợp hai đột biến M1 và M2 có khả năng cao nhất là cặp nào?","opts":["M1 là mất $1$ cặp nucleotide và M2 là thêm $1$ cặp nucleotide nằm cách M1 vài bộ ba (khôi phục khung đọc chuẩn phía sau M2, không gặp bộ ba kết thúc trên đoạn lệch khung ngắn giữa M1 và M2).","M1 là mất toàn bộ gen và M2 là mất tiếp vùng Promoter.","M1 là đột biến vô nghĩa ở bộ ba thứ 5 và M2 là đột biến đồng nghĩa ở bộ ba 100.","M1 và M2 đều là mất $1$ cặp nucleotide."],"ans":0,"exp":"Thí nghiệm kinh điển của Crick - Brenner (1961) chứng minh mã di truyền là mã bộ ba không gối đầu: một đột biến $+1$ và một đột biến $-1$ (hoặc ba đột biến cùng dấu $+1/+1/+1$) gần nhau sẽ triệt tiêu độ lệch khung đọc."},{"id":"MCQ-MO-138","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Công nghệ Gen & PCR","q":"Để xác định xem một mẫu DNA người thu được tại hiện trường có chứa alen đột biến điểm gây bệnh hồng cầu hình liềm (biến đổi trình tự cắt $5'-\\text{CCTGAGG}-3'$ của enzyme giới hạn <i>MstII</i> thành $5'-\\text{CCTGTGG}-3'$ làm MẤT vị trí cắt <i>MstII</i>) hay không, người ta dùng kỹ thuật PCR-RFLP. Nếu đoạn PCR bình thường dài $1.2\\text{ kb}$ chứa đúng 1 vị trí cắt <i>MstII</i> (chia thành $0.5\\text{ kb}$ và $0.7\\text{ kb}$), thì kết quả điện di sản phẩm cắt bằng <i>MstII</i> của một người mang kiểu gen DỊ HỢP TỬ ($Hb^A Hb^S$) sẽ cho bao nhiêu băng DNA trên bản gel?","opts":["$3$ băng có kích thước là $1.2\\text{ kb}$, $0.7\\text{ kb}$ và $0.5\\text{ kb}$.","$2$ băng có kích thước là $0.7\\text{ kb}$ và $0.5\\text{ kb}$.","$1$ băng duy nhất có kích thước $1.2\\text{ kb}$.","$4$ băng có kích thước $1.2, 0.7, 0.5$ và $0.2\\text{ kb}$."],"ans":0,"exp":"Alen lành ($Hb^A$) bị cắt tạo 2 băng ($0.7\\text{ kb} + 0.5\\text{ kb}$). Alen đột biến ($Hb^S$) mất vị trí cắt nên giữ nguyên băng $1.2\\text{ kb}$. Người dị hợp $Hb^A Hb^S$ có cả hai alen nên điện di thấy đủ 3 băng."},{"id":"MCQ-MO-139","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cấu trúc DNA & Siêu xoắn","q":"Trong tế bào vi khuẩn <i>E. coli</i> có DNA dạng vòng kép kín, enzyme DNA gyrase (một loại Topoisomerase II) có vai trò thiết yếu gì trong quá trình nhân đôi DNA, và thuốc kháng sinh nhóm Fluoroquinolone (như Ciprofloxacin) ức chế enzyme này để làm gì?","opts":["DNA gyrase tạo siêu xoắn âm và tháo lực căng xoắn dương tích tụ phía trước chạc ba nhân đôi; Ciprofloxacin khóa phức hợp gyrase-DNA gây đứt gãy sợi kép làm chết vi khuẩn.","DNA gyrase nối các đoạn Okazaki bằng ATP; Ciprofloxacin phá hủy thành Peptidoglycan.","DNA gyrase tổng hợp đoạn mồi RNA.","DNA gyrase chuyển RNA thành DNA."],"ans":0,"exp":"Khi Helicase mở xoắn tại chạc ba, DNA phía trước bị xoắn chặt thêm (siêu xoắn dương). Topoisomerase II (DNA gyrase ở vi khuẩn) cắt tạm thời cả hai mạch, luồn xoắn qua và nối lại để giải tỏa lực căng."},{"id":"MCQ-MO-140","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phiên mã & Định lượng","q":"Một gen ở sinh vật nhân sơ dài $4080\\text{ \\AA}$. Mạch khuôn của gen có $A = 300, T = 200, G = 400, C = 300$. Gen này nhân đôi $2$ lần tạo các gen con, sau đó mỗi gen con đều phiên mã $3$ lần. Tổng số ribonucleotide loại $rU$ và loại $rG$ môi trường nội bào cần cung cấp cho toàn bộ quá trình phiên mã trên lần lượt là:","opts":["$rU = 3600$ và $rG = 3600$.","$rU = 3600$ và $rG = 4800$.","$rU = 1800$ và $rG = 2400$.","$rU = 2400$ và $rG = 4800$."],"ans":0,"exp":"Gen có $2^2 = 4$ gen con $\\times 3$ lần phiên mã $= 12$ phân tử mRNA. Mỗi phân tử mRNA có $rU = A_{\\text{khuôn}} = 300$ và $rG = C_{\\text{khuôn}} = 300 \\Rightarrow rU_{\\text{tổng}} = 12 \\times 300 = 3600$ và $rG_{\\text{tổng}} = 12 \\times 300 = 3600$."},{"id":"MCQ-MO-141","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đột biến & Mất/Thêm Nu","q":"Gen $B$ có $3000$ nucleotide và có tỉ lệ $A/G = 2/3$. Gen $B$ bị đột biến thành alen $b$ có chiều dài không đổi nhưng tỉ lệ $A/G = 602/898$. Dạng đột biến đã xảy ra để chuyển $B$ thành $b$ là:","opts":["Thay thế $1$ cặp $G-C$ bằng $1$ cặp $A-T$.","Thay thế $2$ cặp $G-C$ bằng $2$ cặp $A-T$.","Mất $2$ cặp $G-C$ ở đầu gen và mất $2$ cặp $A-T$ ở cuối gen.","Thay thế $2$ cặp $A-T$ bằng $2$ cặp $G-C$."],"ans":1,"exp":"Ban đầu $N = 3000$ với $A/G = 2/3 \\Rightarrow A = T = 600; G = C = 900$. Alen $b$ có chiều dài không đổi ($N=3000$) và $A/G = 602/898$ (tổng $602+898=1500=N/2$), suy ra $A$ tăng $2$, $G$ giảm $2$ $\\Rightarrow$ thay 2 cặp $G-C$ bằng 2 cặp $A-T$."},{"id":"MCQ-MO-142","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Công nghệ Sinh học","q":"Tại sao khi tạo chuột chuyển gen (Transgenic mouse) mang một gen ngoại lai bằng kỹ thuật vi tiêm (Microinjection) DNA vào tiền nhân đực của hợp tử mới thụ tinh, những con chuột con F0 sinh ra đôi khi là 'thể khảm' (chỉ một số mô mang gen chuyển) hoặc gen chuyển không truyền hết theo tỉ lệ Mendel cho thế hệ F1?","opts":["Do trứng thụ tinh không có nhân.","Do phân tử DNA ngoại lai chèn ngẫu nhiên vào hệ gen sau khi hợp tử đã bắt đầu phân cắt phôi sớm (chỉ một số phôi bào nhận được gen chuyển) hoặc chèn vào nhiều vị trí không đồng nhất trong các dòng tế bào sinh dục.","Do chuột F0 chỉ sinh sản vô tính.","Do DNA ngoại lai tự động biến thành plasmid ở chuột."],"ans":1,"exp":"Nếu DNA vi tiêm tích hợp muộn ở giai đoạn phôi 2 hoặc 4 tế bào thay vì giai đoạn 1 tế bào, cá thể F0 sẽ là thể khảm; hơn nữa người ta cần lai tuyển chọn F1 để thu cá thể đồng nhất có dòng mầm mang gen chuyển."},{"id":"MCQ-MO-143","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Điều hòa Biểu sinh & Histone","q":"Trong mã Histone (Histone code), quá trình Methyl hóa đuôi Histone có tác dụng khác với Acetyl hóa như thế nào?","opts":["Methyl hóa Histone làm trung hòa hoàn toàn điện tích dương giống hệt Acetyl hóa.","Tùy thuộc vào vị trí gốc Lysine được methyl hóa mà tác động có thể trái ngược nhau: ví dụ $\\text{H3K4me3}$ (methyl hóa Lysine 4 của Histone H3) kích hoạt mạnh phiên mã tại Promoter, còn $\\text{H3K9me3}$ và $\\text{H3K27me3}$ lại gây đóng xoắn dị nhiễm sắc và bất hoạt gen.","Acetyl hóa Histone luôn gây tắt hoàn toàn quá trình phiên mã.","Methyl hóa Histone luôn luôn kích hoạt 100% mọi gen."],"ans":1,"exp":"Khác với Acetyl hóa (luôn làm giảm điện tích dương của Lysine $\\rightarrow$ giãn xoắn $\\rightarrow$ bật gen), Methyl hóa giữ nguyên điện tích dương và đóng vai trò bệ gắn cho các protein đọc khác nhau ($\\text{H3K4me3}$ = bật, $\\text{H3K9me3/H3K27me3}$ = tắt)."},{"id":"MCQ-MO-144","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Kỹ thuật CRISPR & Liệu pháp Gen","q":"Liệu pháp chỉnh sửa gen đầu tiên trên thế giới được phê duyệt lâm sàng (Casgevy) điều trị bệnh thiếu máu hồng cầu hình liềm và $\\beta$-thalassemia sử dụng CRISPR-Cas9 KHÔNG trực tiếp sửa đột biến trên gen $\\beta$-globin, mà phá hủy vùng tăng cường (enhancer) của gen <i>BCL11A</i> trong tế bào gốc tủy xương bệnh nhân. Cơ sở sinh học của chiến lược thông minh này là gì?","opts":["Protein <i>BCL11A</i> bình thường đóng vai trò TẮT gen $\\gamma$-globin (Hemoglobin bào thai HbF) sau khi sinh; khi dùng CRISPR phá hủy <i>BCL11A</i>, tế bào hồng cầu TÁI KÍCH HOẠT tổng hợp HbF ($\\alpha_2\\gamma_2$) thay thế cho $\\beta$-globin bị hỏng ($Hb^S$).","Phá hủy <i>BCL11A</i> làm hồng cầu chuyển sang không chứa sắt.","Protein <i>BCL11A</i> là độc tố gây vỡ hồng cầu trực tiếp.","CRISPR-Cas9 chèn thêm gen Hemoglobin của cá voi vào tủy xương."],"ans":0,"exp":"Bất hoạt enhancer đặc hiệu dòng hồng cầu của <i>BCL11A</i> bằng cơ chế NHEJ (hiệu suất rất cao, không cần khuôn HDR) giúp giải phóng gen $\\gamma$-globin bị ức chế từ thời kỳ bào thai, tái sản xuất HbF bù đắp chức năng vận chuyển $O_2$ và ngăn hồng cầu biến dạng hình liềm."},{"id":"MCQ-MO-145","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phiên mã & Thử nghiệm Run-on","q":"Một nhà nghiên cứu muốn phân biệt xem việc tăng nồng độ mRNA của gen $X$ sau khi xử lý tế bào bằng hormone là do TĂNG TỐC ĐỘ PHIÊN MÃ mới hay do TĂNG ĐỘ BỀN (giảm tốc độ phân hủy) của phân tử mRNA đã có sẵn. Nếu dùng chất ức chế hoàn toàn phiên mã (như Actinomycin D) ở thời điểm $t=0$ và đo lượng mRNA $X$ còn lại theo thời gian ở 2 nhóm (có hormone vs đối chứng), kết quả nào chứng minh hormone làm TĂNG ĐỘ BỀN mRNA?","opts":["Ở cả hai nhóm, thời gian bán hủy của mRNA $X$ bằng nhau tuyệt đối.","Sau khi thêm Actinomycin D, lượng mRNA $X$ vẫn tiếp tục tăng vọt lên gấp 10 lần.","mRNA $X$ chuyển hóa ngược lại thành DNA.","Ở nhóm có hormone, thời gian bán hủy ($t_{1/2}$) của mRNA $X$ kéo dài hơn rõ rệt so với nhóm đối chứng (mRNA biến mất chậm hơn sau khi đã khóa hoàn toàn phiên mã)."],"ans":3,"exp":"Khi Actinomycin D chặn đứng hoàn toàn tổng hợp mRNA mới, đường cong suy giảm lượng mRNA theo thời gian chỉ còn phản ánh tốc độ phân hủy (độ bền $t_{1/2}$)."},{"id":"MCQ-MO-146","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Điều hòa Dịch mã & Khởi đầu","q":"Trong tế bào động vật có vú bị nhiễm virus hoặc bị stress thiếu amino acid, một enzyme kinase (như PKR hoặc GCN2) tiến hành phosphoryl hóa yếu tố khởi đầu dịch mã $\\text{eIF2}\\alpha$. Kết quả tức thời của sự phosphoryl hóa $\\text{eIF2}\\alpha$ là gì?","opts":["Ngăn cản sự tái tạo phức hợp $\\text{eIF2-GTP-Met-tRNA}_i$, làm ức chế mạnh quá trình khởi đầu dịch mã tổng thể trong tế bào (ngăn virus lợi dụng ribosome tạo protein virus).","Kích hoạt phiên mã Operon Lac ở tế bào người.","Kích thích cắt bỏ toàn bộ mũ $5'$ của mRNA.","Tăng tốc độ kéo dài chuỗi polypeptide lên gấp 5 lần."],"ans":0,"exp":"Phosphoryl hóa $\\text{eIF2}\\alpha$ biến nó thành chất ức chế cạnh tranh khóa chặt yếu tố trao đổi GTP là $\\text{eIF2B}$, chặn đứng quá trình nạp tRNA mở đầu vào tiểu phần $40\\text{S}$ của ribosome."},{"id":"MCQ-MO-147","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tái bản DNA & Đường kính","q":"Cặp base Purine ($A, G$ có 2 vòng) luôn bắt cặp bổ sung đặc hiệu với Pyrimidine ($T, C$ có 1 vòng) giúp phân tử DNA giữ được đường kính vòng xoắn ổn định là $20\\text{ \\AA}$. Nếu đột biến điểm ngẫu nhiên lắp nhầm một cặp Purine - Purine (ví dụ $A-G$) hoặc Pyrimidine - Pyrimidine (ví dụ $C-T$) trên mạch kép chưa được sửa chữa, cấu trúc cục bộ của xoắn kép DNA sẽ bị biến dạng như thế nào?","opts":["Làm DNA tự chuyển thành RNA ngay lập tức.","Cả phân tử DNA tự động gập thành vòng tròn.","Đường kính tại vị trí sai hỏng vẫn giữ nguyên $20\\text{ \\AA}$ tuyệt đối.","Cặp $A-G$ làm chỗ đó PHÌNH RỘNG ra lớn hơn $20\\text{ \\AA}$, còn cặp $C-T$ làm chỗ đó THẮT HẸP lại nhỏ hơn $20\\text{ \\AA}$, tạo dấu hiệu hình học giúp enzyme sửa chữa MMR nhận diện và cắt bỏ."],"ans":3,"exp":"Sự phình rộng (Pur-Pur: 4 vòng) hay thắt hẹp (Pyr-Pyr: 2 vòng) phá vỡ hình học đều đặn của rãnh xoắn B-DNA (vốn chuẩn cho 3 vòng Pur-Pyr), giúp protein MutS của hệ thống MMR phát hiện cực kỳ chính xác."},{"id":"MCQ-MO-148","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cấu trúc gen & Tiến hóa","q":"So với vi khuẩn (nhân sơ), tại sao tổ chức cấu trúc gen phân mảnh (Exon xen kẽ Intron) lại phổ biến rộng rãi ở sinh vật nhân thực bậc cao và mang lại lợi thế tiến hóa to lớn nào?","opts":["Vì vi khuẩn không có khả năng sao chép các đoạn DNA dài hơn $1000$ bp.","Vì các đoạn Intron mã hóa trực tiếp cho các loại vitamin thiết yếu.","Tạo điều kiện cho hiện tượng 'trộn lẫn Exon' (Exon shuffling) thông qua tái tổ hợp trong các đoạn Intron dài để tạo ra các protein đa miền chức năng mới nhanh chóng, đồng thời cho phép cắt nối thay thế tạo nhiều protein từ 1 gen.","Giúp rút ngắn thời gian nhân đôi DNA xuống chỉ còn vài giây."],"ans":2,"exp":"Mỗi Exon thường mã hóa một miền cấu trúc/chức năng độc lập (domain) của protein; các đoạn Intron đóng vai trò vùng đệm an toàn cho tái tổ hợp hoán vị Exon tạo gen mới trong tiến hóa mà không làm hỏng khung đọc."},{"id":"MCQ-MO-149","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Công nghệ Gen & Định hướng Biểu hiện","q":"Trong kỹ thuật tạo dòng (cloning) một đoạn gen mã hóa dài $1.5\\text{ kb}$ vào vector biểu hiện plasmid, tại sao các nhà sinh học phân tử thường dùng HAI enzyme cắt giới hạn KHÁC NHAU (ví dụ cắt đầu $5'$ bằng <i>EcoRI</i> và đầu $3'$ bằng <i>HindIII</i> — cắt định hướng) thay vì chỉ dùng một enzyme duy nhất?","opts":["Ngăn không cho plasmid tự đóng vòng trở lại khi thiếu đoạn chèn (do 2 đầu dính khác nhau không tự bắt cặp được) và đảm bảo đoạn gen chèn luôn gắn vào ĐÚNG CHIỀU đọc từ Promoter đến Terminator.","Để tạo ra hai đầu tù không cần DNA ligase nối lại.","Vì mỗi plasmid chỉ có thể nhân đôi nếu bị cắt bởi ít nhất 2 enzyme.","Để làm giảm chiều dài của gen mục tiêu đi một nửa."],"ans":0,"exp":"Cắt bằng 1 enzyme tạo 2 đầu dính giống nhau khiến plasmid dễ tự đóng vòng rỗng và gen chèn có $50\\%$ xác suất lắp ngược chiều ($3'\\rightarrow 5'$ so với Promoter). Dùng 2 enzyme khác nhau giải quyết triệt để cả hai vấn đề."},{"id":"MCQ-MO-150","topic":"molecular","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân tích PCR & Điện di","q":"Một phòng thí nghiệm thực hiện phản ứng PCR khuếch đại đoạn gen $X$ từ mẫu mô nghi ngờ nhiễm vi khuẩn lao, kèm theo 2 mẫu đối chứng: Đối chứng dương (chứa DNA chuẩn của vi khuẩn lao) và Đối chứng âm (nước cất vô trùng không chứa DNA khuôn, có đủ mồi, dNTP, Taq). Khi chạy điện di, băng DNA kích thước chuẩn xuất hiện ở cả mẫu bệnh phẩm, mẫu đối chứng dương VÀ mẫu đối chứng âm. Kết luận khoa học chuẩn xác nhất là gì?","opts":["Mẫu bệnh phẩm chắc chắn dương tính 100% với vi khuẩn lao.","Phản ứng đã bị ngoại nhiễm (Contamination) chéo bởi DNA đích vào thuốc thử hoặc nước cất; kết quả mẫu bệnh phẩm KHÔNG đáng tin cậy và phải loại bỏ làm lại từ đầu.","Nước cất tự nhiên chứa sẵn gen của vi khuẩn lao.","Enzyme Taq polymerase bị hỏng không hoạt động."],"ans":1,"exp":"Trong PCR cực kỳ nhạy, đối chứng âm (NTC - No Template Control) bắt buộc phải KHÔNG có băng. Nếu đối chứng âm lên băng chứng tỏ dung dịch mồi/nước/pipette đã bị nhiễm DNA amplicon từ trước (dương tính giả)."}];
